insert into woerter (slug, wort, artikel, ipa, wortart, kategorie, definition, bedeutungen, beispiel) values
  ('a-hetz-haum', 'a Hetz haum', '', '', '', 'Wiener Sprüche, die sitzen!', 'eine Hetz haben', '[{"kategorie": "wörtlich", "text": "\"großen Spaß haben\" (in Anspielung an das einst berühmte [[Hetztheater]] in Wien, in dem seinerzeit Tierhetzen veranstaltet wurden, die damals als allgemeine Volksbelustigung galten)"}, {"kategorie": "allg.", "text": "sich vergnügen, sich köstlich amüsieren, \"einen Riesenspaß haben\", [[eine Gaudi haben]], [[an Koarl haum]]"}]'::jsonb, 'Wia haum a so a Hetz ghobd, dass kaana haamgee woid!'),
  ('wia-haum-a-so-a-hetz-ghobd-dass-kaana-haamgee-woid', 'Wia haum a so a Hetz ghobd, dass kaana haamgee woid!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Wir haben eine solche Hetz gehabt, dass keiner heimgehen wollte!', '[{"kategorie": "wörtlich", "text": "\"Wir hatten so viel Spaß, dass niemand nach Hause wollte!\"  2. Wir haben uns so köstlich amüsiert, dass keiner heimgehen wollte!  3. Wir hatten so einen Riesenspaß, dass niemand ans Nachhausegehen gedacht hat!"}]'::jsonb, 'a Hetz haum'),
  ('a-gaudi-haum', 'a Gaudi haum', '', '', '', 'Wiener Sprüche, die sitzen!', 'eine Gaudi haben', '[{"kategorie": "wörtlich", "text": "\"großen Spaß haben\"  (vom lateinischen \"gaudium\" = \"Spaß\")"}, {"kategorie": "allg.", "text": "sich vergnügen, sich köstlich amüsieren, \"einen Riesenspaß haben\", [[eine Hetz haben]], [[an Koarl haum]]"}]'::jsonb, 'So a Gaudi wia heit hauma scho laung nimma ghobd - I hob mi hoibad aupischd vua Lochn!'),
  ('so-a-gaudi-wia-heit-hauma-scho-laung-nimma-ghobd-i-hob-mi-hoibad-aupischd-vua-lochn', 'So a Gaudi wia heit hauma scho laung nimma ghobd - I hob mi hoibad aupischd vua Lochn!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'So eine Gaudi wie heute haben wir schon lang nicht mehr gehabt - ich hab mich halb angepischt vor Lachen!', '[{"kategorie": "wörtlich", "text": "\"So einen Spaß hatten wir schon ewig nicht mehr – ich hab mir fast in die Hose gemacht vor Lachen!\"  2. Das war ein Riesenspaß heute – ich hab mich weggeschmissen vor Lachen!  3. Bruder, ich hab fast den Verstand verloren vor Lachen – so eine [[Batzenhetz]] hatten wir ewig nicht mehr!"}]'::jsonb, 'a Gaudi haum'),
  ('an-muadskoarl-haum', 'an Muadskoarl haum', '', '', '', 'Wiener Sprüche, die sitzen!', 'einen Mordskarl haben', '[{"kategorie": "wörtlich", "text": "\"einen Riesenspaß haben\" (in Anspielung an das seinerzeit berühmte [[Carltheater]], einer Volksbühne in Wien, in der man jede Menge Spaß serviert bekam)"}, {"kategorie": "allg.", "text": "sich hammermäßig vergnügen, sich köstlichst amüsieren, [[einen Heidenspaß haben]], [[eine Mordsgaudi haben]], [[eine Batzenhetz haben]]"}]'::jsonb, 'a Botznhetz haum'),
  ('an-botznkoarl-haum', 'an Botznkoarl haum', '', '', '', 'Wiener Sprüche, die sitzen!', 'einen Batzenkarl haben', '[{"kategorie": "wörtlich", "text": "\"einen Riesenspaß haben\" (in Anspielung an das seinerzeit berühmte [[Carltheater]], einer Volksbühne in Wien, in der man jede Menge Spaß serviert bekam)"}, {"kategorie": "allg.", "text": "sich hammermäßig vergnügen, sich köstlichst amüsieren, [[einen Heidenspaß haben]], [[eine Mordsgaudi haben]], [[eine Batzenhetz haben]]"}]'::jsonb, ''),
  ('a-botznhetz-haum', 'a Botznhetz haum', '', '', '', 'Wiener Sprüche, die sitzen!', 'eine Batzenhetz haben', '[{"kategorie": "wörtlich", "text": "\"einen Riesenspaß haben\" (in Anspielung auf das einst berühmte [[Hetztheater]] in Wien, in dem seinerzeit Tierhetzen veranstaltet wurden, die damals als allgemeine Volksbelustigung galten)"}, {"kategorie": "allg.", "text": "sich hammermäßig vergnügen, sich köstlichst amüsieren, [[einen Heidenspaß haben]], [[eine Mordsgaudi haben]], [[an Muadskoarl haum]]"}]'::jsonb, 'Weara Botznhetz haum wüü, deea geed aufd Wiina Wiisn!'),
  ('weara-botznhetz-haum-wueue-deea-geed-aufd-wiina-wiisn', 'Weara Botznhetz haum wüü, deea geed aufd Wiina Wiisn!', '', '', '', 'Wienerisches aus Musik, Kunst, Kultur & Medien', 'Wer eine Batzenhetz haben will, der geht auf die Wiener Wiesen!', '[{"kategorie": "wörtlich", "text": "\"Wer einen Riesenspaß haben will, der geht aufs Wiener Wiesenfest!\"  2. Lust auf eine Mordsgaudi? Dann ab zum Wiener Wiesenfest!  3. Wenn du dich hammermäßig vergnügen möchtest, führt kein Weg am Wiener Wiesenfest vorbei!"}]'::jsonb, 'a Botznhetz haum'),
  ('a-muadsgaudi-haum', 'a Muadsgaudi haum', '', '', '', 'Wiener Sprüche, die sitzen!', 'eine Mordsgaudi haben', '[{"kategorie": "wörtlich", "text": "\"einen Mordsspaß haben\" (vom lateinischen \"gaudium\" = \"Spaß\")"}, {"kategorie": "allg.", "text": "sich hammermäßig vergnügen, sich köstlichst amüsieren, [[einen Heidenspaß haben]], [[eine Batzenhetz haben]], [[an Muadskoarl haum]]"}]'::jsonb, ''),
  ('an-heidnschbaass-haum', 'an Heidnschbaass haum', '', '', '', 'Wiener Sprüche, die sitzen!', 'einen Heidenspaß haben', '[{"kategorie": "wörtlich", "text": "\"einen Riesenspaß haben\" (eigtl. \"einen Spaß wie bei den Heiden haben\")"}, {"kategorie": "allg.", "text": "sich hammermäßig vergnügen, sich köstlichst amüsieren, [[eine Mordsgaudi haben]], [[eine Batzenhetz haben]], [[an Muadskoarl haum]]"}]'::jsonb, 'Bia, Bloosmusik und Broodwiaschdl - wia haum an Heidnschbaass ghobd!'),
  ('bia-bloosmusik-und-broodwiaschdl-wia-haum-an-heidnschbaass-ghobd', 'Bia, Bloosmusik und Broodwiaschdl - wia haum an Heidnschbaass ghobd!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Bier, Blasmusik und Bratwurst – wir haben einen Heidenspaß gehabt!', '[{"kategorie": "wörtlich", "text": "\"Bier, Blasmusik und Bratwurst – wir hatten eine Mordsgaudi!\"  2. So viel Stimmung, Musik und gutes Essen – wir haben uns hammermäßig amüsiert!  3. Gute Stimmung, deftiges Essen und tolle Musik – wir alle hatten einen Riesenspaß!"}]'::jsonb, ''),
  ('ois-kinda-hauma-min-kautschi-riisige-bloosn-gmochd-bis-uns-vua-da-noosn-zaplotzd-san', 'Ois Kinda hauma min Kautschi riisige Bloosn gmochd, bis uns vua da Noosn zaplotzd san!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Als Kinder haben wir mit dem Kaugummi riesige Blasen gemacht, bis sie uns vor der Nase zerplatzt sind!', '[{"kategorie": "wörtlich", "text": "\"Als Kinder pusteten wir aus Kaugummi riesige Ballons, bis sie uns vor der Nase zerplatzt sind!\"  2. Als Kinder konnten wir stundenlang Kaugummi-Blasen machen, bis sie uns bäm! auf der Nase geklebt sind!  3. Aus einer kleinen Kaugummikugel zauberten wir als Kinder wahre Riesenballons, bis sie uns vor der Nase zerplatzten!"}]'::jsonb, ''),
  ('kavalia-mid-schdrupfn', 'Kavalia mid Schdrupfn', '', '', '', 'Wiener Wörter mit schillernder Geschichte', 'Kavalier mit Strupfen', '[{"kategorie": "wörtlich", "text": "\"Kavalier mit Strupfen\" (von [[Strupf]]=\"Anziehlasche an hohen Männerschuhen\")"}, {"kategorie": "fig., scherzhaft für", "text": "\"Sonntagskavalier mit Montagsmanieren\", \"Heuchler mit Manschettenknöpfen\", \"falscher Galan\", \"Samthandschuh-Typ\", \"aufgedonnerter Blender\""}]'::jsonb, 'Ea gibd in Salonlööwn - owa in Woaheid isa a Kavalia mid Schdrupfn!'),
  ('ea-gibd-in-salonloeoewn-owa-in-woaheid-isa-a-kavalia-mid-schdrupfn', 'Ea gibd in Salonlööwn - owa in Woaheid isa a Kavalia mid Schdrupfn!', '', '', '', 'Wiener Wörter mit schillernder Geschichte', 'Er gibt den Salonlöwen - aber in Wahrheit ist er ein Kavalier mit Strupfen!', '[{"kategorie": "wörtlich", "text": "\"Er gibt den Salonlöwen - aber in Wahrheit ist er ein Sonntagskavalier mit Montagsmanieren!\"  2. Er spielt den Grandseigneur, doch sein Benehmen verrät den Tagedieb!  3. Er ist ein Don Juan zweiter Güte - Luxus-Schale, Billig-Inhalt!"}]'::jsonb, 'Kavalia mid Schdrupfn'),
  ('si-zum-koarl-mochn', 'si zum Koarl mochn', '', '', '', 'Wiener Sprüche, die sitzen!', 'sich zum Karl machen', '[{"kategorie": "wörtlich", "text": "\"sich zum Narren machen\""}, {"kategorie": "allg.", "text": "sich lächerlich machen, sich zum Affen machen, sich zum Gespött machen, sich bis auf die Knochen blamieren"}]'::jsonb, 'Waunnsd in dem Aufzug zum Festl geesd, mochst di zum Koarl!'),
  ('waunnsd-in-dem-aufzug-zum-festl-geesd-mochst-di-zum-koarl', 'Waunnsd in dem Aufzug zum Festl geesd, mochst di zum Koarl!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Wenn du in diesem Aufzug zum Fest gehst, machst du dich zum Karl!', '[{"kategorie": "wörtlich", "text": "\"Wenn du in diesem Aufzug zum Fest gehst, machst du dich zum Narren!\"  2. Wenn du in diesem Outfit zum Fest gehst, blamierst du dich bis auf die Knochen!  3. In diesem Look wirst du zur Lachnummer des Abends!"}]'::jsonb, 'si zum Koarl mochn'),
  ('si-an-koarl-aus-wem-mochn', 'si an Koarl aus wem mochn', '', '', '', 'Wiener Sprüche, die sitzen!', 'sich einen Karl aus jemandem machen', '[{"kategorie": "wörtlich", "text": "\"sich einen Narren aus jemandem machen\""}, {"kategorie": "", "text": "\"sich über jemanden lustig machen\""}, {"kategorie": "", "text": "\"jemanden zum Affen machen\""}, {"kategorie": "", "text": "\"jemanden vor allen zum Deppen machen\""}, {"kategorie": "", "text": "\"jemanden vor allen lächerlich machen\""}]'::jsonb, 'De Oide mochd si an Koarl aus mia - und des is ned schee von ia!'),
  ('si-an-koarl-mit-wem-mochn', 'si an Koarl mit wem mochn', '', '', '', 'Wiener Sprüche, die sitzen!', 'sich einen Karl mit jemandem machen', '[{"kategorie": "wörtlich", "text": "\"sich einen Spaß mit jemandem machen\""}, {"kategorie": "", "text": "\"sich über jemanden lustig machen\""}, {"kategorie": "", "text": "\"einen Narren aus jemandem machen\""}, {"kategorie": "", "text": "\"jemanden zum Affen machen\""}, {"kategorie": "", "text": "\"jemanden vor allen lächerlich machen\""}]'::jsonb, 'Moch da mit mia nua jo kan Koarl!'),
  ('moch-da-mit-mia-nua-jo-kan-koarl', 'Moch da mit mia nua jo kan Koarl!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Mach dir mit mir nur ja keinen Karl!', '[{"kategorie": "wörtlich", "text": "\"Mach dich über mich nur ja nicht lustig!\"  2. Mach mich nur ja nicht zu deinem Narren!  3. Versuch nur ja nicht, mich lächerlich zu machen!"}]'::jsonb, 'si an Koarl mit wem mochn'),
  ('de-oide-mochd-si-an-koarl-aus-mia-und-des-is-ned-schee-von-ia', 'De Oide mochd si an Koarl aus mia - und des is ned schee von ia!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Die Alte macht einen Karl aus mir - und das ist nicht schön von ihr!', '[{"kategorie": "wörtlich", "text": "\"Die Alte macht einen Narren aus mir - und das ist nicht schön von ihr!\"  2. Die Frau macht mich komplett zum Deppen – und das ist echt mies von ihr!  3. Die Alte macht sich auf meine Kosten über mich lustig – das geht gar nicht!"}]'::jsonb, 'si an Koarl aus wem mochn'),
  ('in-koarl-fia-olle-mochn', 'in Koarl fia olle mochn', '', '', '', 'Wiener Sprüche, die sitzen!', 'den Karl für alle machen', '[{"kategorie": "wörtlich", "text": "\"den Clown für alle geben\""}, {"kategorie": "allg.", "text": "sich für alle zum Narren machen, sich für alle zum Affen machen, den [[Kasperl]] für alle machen"}]'::jsonb, 'Ea glaubd imma, ea muass in Koarl fia olle mochn, und meakd dabei ned, wia peinlich a is!'),
  ('ea-glaubd-imma-ea-muass-in-koarl-fia-olle-mochn-und-meakd-dabei-ned-wia-peinlich-a-is', 'Ea glaubd imma, ea muass in Koarl fia olle mochn, und meakd dabei ned, wia peinlich a is!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Er glaubt immer, er muss den Karl für alle machen, und merkt dabei nicht, wie peinlich er ist!', '[{"kategorie": "wörtlich", "text": "\"Er glaubt immer, er muss den Clown für alle geben, und merkt dabei nicht, wie peinlich er ist!\"  2. Er meint, er muss sich für alle zum Narren machen, und merkt dabei nicht, wie peinlich das rüberkommt!  3. Er glaubt, er muss ständig den Witzbold spielen – in Wahrheit bringt er damit aber alle nur in Verlegenheit!"}]'::jsonb, ''),
  ('in-kaschbal-fia-olle-mochn', 'in Kaschbal fia olle mochn', '', '', '', 'Wiener Sprüche, die sitzen!', 'den Kasperl für alle machen', '[{"kategorie": "wörtlich", "text": "\"den Clown für alle geben\" (von [[Kasperl]]=\"Hanswurst\")"}, {"kategorie": "", "text": "sich für alle zum Narren machen, sich für alle zum Affen machen, den [[Karl]] für alle machen"}]'::jsonb, 'Ea glaubd imma, ea muass in Kaschbal fia olle mochn, und meakd dabei ned, wia peinlich a is!'),
  ('ea-glaubd-imma-ea-muass-in-kaschbal-fia-olle-mochn-und-meakd-dabei-ned-wia-peinlich-a-is', 'Ea glaubd imma, ea muass in Kaschbal fia olle mochn, und meakd dabei ned, wia peinlich a is!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Er glaubt immer, er muss den Kasperl für alle machen, und merkt dabei nicht, wie peinlich er ist!', '[{"kategorie": "wörtlich", "text": "\"Er glaubt immer, er muss den Clown für alle geben, und merkt dabei nicht, wie peinlich er ist!\"  2. Er meint, er muss sich für alle zum Narren machen, und merkt dabei nicht, wie peinlich das rüberkommt!  3. Er glaubt, er muss ständig den Witzbold spielen – in Wahrheit bringt er damit aber alle nur in Verlegenheit!"}]'::jsonb, ''),
  ('moch-ma-uns-an-koarl', 'Moch ma uns an Koarl!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Machen wir uns einen Karl!', '[{"kategorie": "wörtlich", "text": "\"Machen wir uns eine Gaudi!\"  2. \"Lasst uns Spaß haben!\"   3. Machen wir uns eine lustige Zeit!"}]'::jsonb, ''),
  ('des-is-a-koarl', 'Des is a Koarl!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Das ist ein Karl!', '[{"kategorie": "wörtlich", "text": "\"Das ist ein Spaß!\"  2. (allg.) Das ist ein Vergnügen!  3. Das ist ein Klamauk!  4. Das ist eine [[Gaudee]]!"}]'::jsonb, ''),
  ('scheiss-au-koarl', 'Scheiss au, Koarl!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Scheiß an, Karl!', '[{"kategorie": "wörtlich, Ausruf der Gelassenheit und Gleichgültigkeit", "text": "\"Ach scheiß drauf, Kumpel!\"  2. (scherzhaft für): \"Wen juckt''s, Alter?\"  3. \"Na und, meine Güte!\"  4. \"Na und wenn schon, Bruder!\"  5. \"Pfeif drauf, Alter!\""}]'::jsonb, ''),
  ('si-ookoarln', 'si ookoarln', '', '', '', 'Grundwortschatz Wienerisch', 'sich abkarlen', '[{"kategorie": "wörtlich", "text": "\"sich vor Spaß kaum halten können\" (von [[Karl]]=\"Spaß\", in Anspielung auf das seinerzeit berühmte[[Carltheater]], eine Volksbühne in Wien, in der man jede Menge Spaß serviert bekam)"}, {"kategorie": "allg.", "text": "sich krumm und bucklig lachen, sich kaputtlachen, \"Tränen lachen über jemanden\", [[sich]] abbröseln, [[sich]] abpecken, [[sich]] abhauen"}]'::jsonb, 'De haum si olle ookoarld iwa eam, wiara mitn offanan Hoosntiarl duachs Festzööd grennd is!'),
  ('de-haum-si-olle-ookoarld-iwa-eam-wiara-mitn-offanan-hoosntiarl-duachs-festzoeoed-grennd-is', 'De haum si olle ookoarld iwa eam, wiara mitn offanan Hoosntiarl duachs Festzööd grennd is!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Die haben sich alle abgekarlt über ihn, wie er mit offenem Hosentor durchs Festzelt gerannt ist!', '[{"kategorie": "wörtlich", "text": "\"Die haben sich alle totgelacht über ihn, als er mit offenem Hosenstall durchs Festzelt gelaufen ist!\"  2. Die haben alle Tränen über ihn gelacht, als er mit offener Hose ins Festzelt gerannt kam!  3. Die konnten sich alle vor Spaß gar nicht mehr halten, als er mit offenem Hosenschlitz die Bühne im Festzelt gestürmt hat!"}]'::jsonb, 'si ookoarln'),
  ('karottn-haum-vueue-vitamin-a-und-san-guad-fiad-aung', 'Karottn haum vüü Vitamin A und san guad fiad Aung!', '', '', '', 'Botanik und Pflanzen auf Wienerisch', 'Karotten haben viel Vitamin A und sind gut für die Augen!', '[{"kategorie": "wörtlich", "text": "\"Karotten sind reich an Vitamin A, welches die Sehkraft stärkt!\"  2. In Karotten steckt jede Menge Vitamin A – gut für scharfe Augen!  3. Karotten enthalten Beta-Carotin, das im Körper zu Vitamin A umgewandelt wird und die Augen stärkt!"}]'::jsonb, ''),
  ('in-wean-host-karottn-moeoere-is-a-wuat-fia-leit-de-schnitzl-mit-ketschap-essn', 'In Wean host Karottn - Mööre is a Wuat fia Leit, de Schnitzl mit Ketschap essn!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'In Wien hast du Karotten – Möhre ist ein Wort für Leute, die Schnitzel mit Ketchup essen!', '[{"kategorie": "wörtlich", "text": "\"In Wien sagt man Karotte – ''Möhre'' ist ein Wort für Leute, die Schnitzel mit Ketchup essen!\"  2. In Wien gibt’s Karotten – „Möhre“ sagen nur die, die Schnitzel mit Ketchup verunstalten!  3. ''Karotte'' sagt der Wiener – ''Möhre'' sagen nur die, die glauben, Schnitzel braucht Tomatensauce!"}]'::jsonb, ''),
  ('dea-schdeckd-sei-karottn-iwaroi-eine-wos-nuara-bissl-woam-is', 'Dea schdeckd sei Karottn iwaroi eine, wos nuara bissl woam is!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Der steckt seine Karotte überall rein, wo''s nur ein bisschen warm ist!', '[{"kategorie": "wörtlich", "text": "\"Der steckt seinen Prügel überall rein, wo’s ein bisschen warm ist!\"  2. Der steckt sein Gurkerl überall rein, wo’s ein bisschen dampft!  3. Der vögelt alles an, was nicht bei drei auf ''nem Baum ist!"}]'::jsonb, ''),
  ('des-karottnballett-is-de-aanzige-taunzgruppn-wo-jeeda-an-kiiwae-schdott-a-scheens-weiss-rockal-schwingd', 'Des Karottnballett is de aanzige Taunzgruppn, wo jeeda an Kiiwä schdott a scheens, weiss Rockal schwingd!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Das Karottenballett ist die einzige Tanzgruppe, wo jeder einen Kübel statt ein schönes, weißes Röckchen schwingt!', '[{"kategorie": "wörtlich", "text": "\"Das Wiener Karottenballett ist die einzige Ballettgruppe, die Kübel statt Röckchen schwingt!\"  2. Das Karottenballett ist die einzige Tanzpartie, wo’s ''nen Kübel schupfn statt im Tutu hupfn!  3. Beim Wiener Karottenballett rennt keiner im weißen Röckchen rum, da siehst du nur Kübelschupfer in orangen Leibchen!"}]'::jsonb, ''),
  ('gee-schneid-ma-noo-zwaa-kotlett-ausn-karree-owa', 'Gee, schneid ma noo zwaa Kotlett ausn Karree owa!', '', '', '', 'Wiener Fleischhauer-Slang', 'Geh, schneid mir noch zwei Koteletts aus dem Karree runter!', '[{"kategorie": "wörtlich", "text": "\"Könnten Sie mir noch zwei Koteletts aus dem Lendenrippenstück runterschneiden?\"  2. Bitte zwei Koteletts vom Rücken, am Knochen geschnitten!  3. Schneiden Sie mir bitte noch zwei Stück vom Rippenkamm runter!"}]'::jsonb, ''),
  ('amoi-ums-karree', 'Amoi ums Karree!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Einmal ums Karree!', '[{"kategorie": "wörtlich", "text": "\"Einmal um den Häuserblock!\"  2. [[Amoi]] uman Bau!  3. Einmal rund um die Siedlung!"}]'::jsonb, ''),
  ('amoi-uman-bau', 'Amoi uman Bau!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Einmal um den Bau!', '[{"kategorie": "wörtlich", "text": "\"Einmal um den Häuserblock!\"  2. [[Einmal]] ums Karree!  3. Einmal rund um die Siedlung!"}]'::jsonb, ''),
  ('eadaepfaepuffa-schmeckn-aum-bestn-waunns-aussn-knusprig-und-innan-waach-san', 'Eadäpfäpuffa schmeckn aum bestn, waunns aussn knusprig und innan waach san!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Erdäpfelpuffer schmecken am besten, wenn sie außen knusprig und innen weich sind!', '[{"kategorie": "wörtlich", "text": "\"Kartoffelpuffer schmecken am besten, wenn sie außen kross und innen zart sind!\"  2. Kartoffelpuffer sind ein Genuss, wenn sie außen wie Chips knuspern und innen wie Püree schmecken!  3. Erdäpfelpuffer sind am besten, wenn sie außen resch und innen flaumig sind!"}]'::jsonb, ''),
  ('so-vueuera-bei-ia-a-kaschuliad-hod-aum-end-hoda-doch-auf-da-kautsch-schloofn-miassn', 'So vüüra bei ia a kaschuliad hod, aum End hoda doch auf da Kautsch schloofn miassn!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'So viel er bei ihr auch kaschuliert hat - am Ende musste er doch auf der Couch schlafen!', '[{"kategorie": "wörtlich", "text": "\"So sehr er sich bei ihr auch einschmeichelte – am Ende landete er doch auf der Couch!\"  2. So sehr er sie auch umgarnte – am Ende musste er trotzdem auf dem Sofa übernachten!  3. So sehr er auch den Schmusekater gab – am Ende hieß es: „Ab aufs Sofa!"}]'::jsonb, ''),
  ('mei-kostn-quiitschd-waunnsd-eam-aufmochsd-fost-wiara-oida-tiarlschdeea', 'Mei Kostn quiitschd, waunnsd eam aufmochsd - fost wiara oida Tiarlschdeea!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Mein Kasten quietscht, wenn du ihn aufmachst – fast wie ein alter Türsteher!', '[{"kategorie": "wörtlich", "text": "\"Mein Kleiderschrank quietscht beim Aufmachen – wie ein Türsteher nach 30 Jahren Disko!\"  2. Mein Schrank stöhnt beim Aufmachen – als hätte er schon zu viele Nachtschichten hinter sich!  3. Mein Kasten kreischt beim Aufmachen – wie ein Türsteher, dem man den Ausweis nicht zeigt!"}]'::jsonb, ''),
  ('wos-haums-uns-do-fiaran-kostn-mittn-ind-innanschdodt-baud', 'Wos haums uns do fiaran Kostn mittn ind Innanschdodt baud?', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Was haben sie uns da für einen Kasten mitten in die Innenstadt gebaut?', '[{"kategorie": "wörtlich", "text": "\"Was haben die uns da für einen Klotz mitten in die Innenstadt gesetzt?\"  2. Was für einen Betonbunker haben sie uns da mitten ins Zentrum gepflanzt?  3. Was für ein Riesending haben die uns da mitten in die Innenstadt geklotzt?"}]'::jsonb, ''),
  ('da-neiche-tiarlschdeea-is-a-richtiga-kostn-zwaa-maeaeta-grooss-und-braad-wiara-schraunk', 'Da neiche Tiarlschdeea is a richtiga Kostn -  zwaa Määta grooss und braad wiara Schraunk!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Der neue Türsteher ist ein richtiger Kasten – zwei Meter groß und breit wie ein Schrank!', '[{"kategorie": "wörtlich", "text": "\"Der neue Türsteher ist ein wahrer Koloss – hoch und kräftig wie ein Schrank!\"  2. Der neue Türsteher ist ein Berg von einem Mann – riesig, massiv gebaut und genauso breit wie hoch!  3. Der neue Türsteher ist eine imposante Erscheinung – ein Block Beton auf zwei Beinen!"}]'::jsonb, ''),
  ('draa-in-kostn-leisa-i-vaschdee-jo-mei-eigans-wuad-ned-mea', 'Draa in Kostn leisa, I vaschdee jo mei eigans Wuad ned mea!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Dreh den Kasten leiser - ich versteh ja mein eigenes Wort nicht mehr!', '[{"kategorie": "wörtlich", "text": "\"Mach den Fernseher leiser – ich kann mich ja selbst nicht mehr hören!\"  2. Stell den Fernsehapparat leiser – ich verstehe ja kein Wort mehr!  3. Stell den Flimmerkasten leiser – sonst platzen mir die Ohren!"}]'::jsonb, ''),
  ('host-aufn-foamulaa-aeae-es-richtige-kaastl-aukreizd', 'Host aufn Foamulaa ää es richtige Kaastl aukreizd?', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Hast du auf dem Formular eh des richtige Kastl angekreuzt?', '[{"kategorie": "wörtlich", "text": "\"Hast du im Formular eh das richtige Kästchen angekreuzt?\"  2. Hast du im Formular das passende Feld markiert?  3. Hast du auf dem Formular dein [[Hakerl]] eh im richtigen Ankreuzfeld gemacht?"}]'::jsonb, ''),
  ('host-aeae-a-hakal-im-aansakaastl-gmochd-bevuasd-weidaklickd-host', 'Host ää a Hakal im Aansakaastl gmochd, bevuasd weidaklickd host?', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Hast du eh ein Hakerl im Einserkästchen gemacht, bevor du weitergeklickt hast?', '[{"kategorie": "wörtlich", "text": "\"Hast du eh ein Kreuzchen im Einserkästchen gemacht, bevor du weitergeklickt hast?\"  2. Hast du eh das Kästchen mit der Nummer 1 angekreuzt, bevor du weitergeklickt hast?  3. Hast du das Ankreuzfeld 1 markiert, bevor du weitergeklickt hast?"}]'::jsonb, ''),
  ('im-aansakastl-kommentiad-da-schaeaefredaktoea-heite-de-neichn-biapreise', 'Im Aansakastl kommentiad da Schääfredaktöa heite de neichn Biapreise!', '', '', '', 'Wienerisches aus Musik, Kunst, Kultur & Medien', 'Im Einserkastl kommentiert der Chefredakteur heute die neuen Bierpreise!', '[{"kategorie": "wörtlich, Zeitungswesen", "text": "\"In der Titelglosse kommentiert der Chefredakteur heute die neuen Bierpreise!\"  2. In der heutigen Leitkolumne beleuchtet der Chefredakteur die neuen Bierpreise!  3. In der Aufmacher-Glosse gibt’s heute vom Chefredakteur ordentlich gegen die Bierpreise!"}]'::jsonb, ''),
  ('schaust-scho-wiida-in-gaunzn-toog-ins-kaastl', 'Schaust scho wiida in gaunzn Toog ins Kaastl?', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Schaust du schon wieder den ganzen Tag ins Kastl?', '[{"kategorie": "wörtlich", "text": "\"Glotzt du schon wieder den ganzen Tag in den Flimmerkasten?\"  2. Tust du den ganzen Tag schon wieder nichts als fernsehen?  3. Verbringst du schon wieder den ganzen Tag vor dem Fernsehapparat?"}]'::jsonb, ''),
  ('klopp-eam-zsaumm-wiara-kalzoone-den-itaka', 'Klopp eam zsaumm wiara Kalzoone, den Itaka!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Klapp ihn zusammen wie eine Calzone, den Itaka!', '[{"kategorie": "wörtlich, Wrestlerjargon", "text": "\"Falt ihn zusammen wie ’ne Pizza Calzone, den Itaker!\"  2. Mach ihn platt wie ’ne Flunder, den Italiener!  3. Zerleg ihn wie ’nen alten Klapptisch, den Spaghettifresser!"}]'::jsonb, ''),
  ('friara-haum-uns-de-katzlmocha-no-soeoewagschnitzde-hoizleffaen-vadraad-heit-kummans-und-flaadan-uns-tonnanweis-de-schwammaln-ausn-woid', 'Friara haum uns de Katzlmocha no sööwagschnitzde Hoizleffän vadraad - heit kummans und flaadan uns tonnanweis de Schwammaln ausn Woid!', '', '', '', 'Wiener Wörter mit schillernder Geschichte', 'Früher haben uns die Katzelmacher noch selbstgeschnitzte Holzlöffel verdreht - heute kommen sie und fladern uns tonnenweise die Schwammerln aus dem Wald!', '[{"kategorie": "wörtlich", "text": "\"Früher haben uns die italienischen Löffelverkäufer noch selbstgeschnitzte Holzlöffel verhökert - heute kommen sie und stehlen uns tonnenweise Pilze aus dem Wald!\"  2. Früher brachten die italienischen Händler noch handgeschnitzte Holzlöffel mit – heute klauen sie tonnenweise Pilze aus unseren Wäldern!  3. Früher haben uns die Italiener noch eigene Holzlöffel geschnitzt und verkauft – heut stibitzen sie uns tonnenweise die Pilze aus’m Wald!"}]'::jsonb, ''),
  ('katzinga-san-noamal-schbagettifressa-owa-seid-neichastn-flaadans-uns-kiloweis-de-schwammaln-ausn-woid', 'Katzinga san noamal Schbagettifressa - owa seid neichastn flaadans uns kiloweis de Schwammaln ausn Woid!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Katzinger sind normal Spaghettifresser - aber seit neuestem fladern sie uns kiloweise die Schwammerln aus dem Wald!', '[{"kategorie": "wörtlich", "text": "\"Italiener sind normal Spaghettifresser - aber seit neuestem klauen sie uns kiloweise die Pilze aus dem Wald!\"  2. Normalerweise kennt man die Italiener als Spaghettifresser – aber neuerdings holen sie säckeweise die Pilze aus unseren Wäldern!  3. Bisher haben die Italiener vor allem Nudeln gefressen – aber jetzt stopfen sie sich die Körbe mit Pilzen aus unseren Wäldern voll!"}]'::jsonb, ''),
  ('da-oide-deewich-faungd-scho-wiida-z-katzln-au-seit-de-kotz-drauf-schloofd', 'Da oide Deewich faungd scho wiida z''katzln au, seit de Kotz drauf schloofd!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Der alte Teppich fängt schon wieder zu katzeln an, seit die Katze drauf schläft!', '[{"kategorie": "wörtlich", "text": "\"Der alte Teppich hat schon wieder Katzen­geruch angenommen, seit die Katze darauf schläft!\"  2. Der alte Teppich mieft schon wieder nach Katze, seit die Mieze darauf pennt!  3. Der alte Teppich beginnt erneut, nach Katze zu müffeln, seit die Katze darauf liegt"}]'::jsonb, ''),
  ('des-is-kaa-koa-des-is-a-kotzngschraa', 'Des is kaa Koa, des is a Kotzngschraa!', '', '', '', 'Wienerisches aus Musik, Kunst, Kultur & Medien', 'Das ist kein Chor, das ist ein Katzengeschrei!', '[{"kategorie": "wörtlich", "text": "\"Das ist kein Chor, das klingt wie Katzenjammer!\"  2. Das ist kein Chorgesang, das klingt nach einem Haufen jaulender Katzen!  3. Das ist kein Chor, das ist ein einziges Katzengekreische!"}]'::jsonb, ''),
  ('friara-is-kotzngschraa-fix-auf-da-koatn-von-an-jeedn-wiatshaus-gschdaundn-heit-is-a-echte-raritaet', 'Friara is Kotzngschraa fix auf da Koatn von an jeedn Wiatshaus gschdaundn - heit is a echte Rarität!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Früher ist ''Kotzngschraa'' fix auf der Karte eines jeden Wirtshauses gestanden - heute ist es eine echte Rarität!', '[{"kategorie": "wörtlich", "text": "\"Einst war ''Kotzngschraa'' ein fester Bestandteil jeder Wirtshauskarte – heute ist es kaum mehr zu bekommen!\"  2. Früher gab’s ''Kotzngschraa'' in jedem Beisl – heute kennt’s kaum mehr wer!  3. Früher war ''Kotzngschraa'' an jeder Ecke zu haben – heute ist es ein rares Stück Wirtshauskultur!"}]'::jsonb, ''),
  ('hea-auf-mit-dem-kaudawoeoesch-und-kumm-endlich-zum-punkt', 'Hea auf mit dem Kaudawöösch und kumm endlich zum Punkt!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Hör auf mit dem Kauderwelsch und komm endlich zum Punkt!', '[{"kategorie": "wörtlich", "text": "\"Hör auf mit dem Geschwafel und komm endlich zum Punkt!\"  2. Hör auf mit dem wirren Gerede und komm endlich zur Sache!  3. Genug mit dem Wortsalat – sag''s endlich grad heraus!"}]'::jsonb, ''),
  ('scheiss-au-i-haed-in-kawall-ned-schbueuen-soin-jetzt-is-de-foab-tood', 'Scheiss au, I häd in Kawall ned schbüün soin - jetzt is de Foab tood!', '', '', '', 'Wiener Kartentipplerjargon', 'Mist, ich hätte den Kavall nicht spielen sollen, jetzt ist die Farbe tot!', '[{"kategorie": "wörtlich, Kartenspielerjargon", "text": "\"Verdammt, ich hab den Reiter zu früh gespielt – jetzt ist die Farbe gestorben!\"  2. Scheiße, den Kavall hab ich verschossen – jetzt ist die Farbe erledigt!  3. So ein Schmarren – ich hätte den Reiter nicht spielen dürfen, jetzt ist es aus mit der Farbe!"}]'::jsonb, ''),
  ('gschdiiss-papa', 'Gschdiiss-Papa', 'der', '', '', 'Wiener Kartentipplerjargon', 'Gstieß-Papa', '[{"kategorie": "wörtlich, Kartenspielerjargon", "text": "\"Sküs-Papa\" (scherzhafte Bezeichnung der Kartenspieler für den [[Sküs]], die höchste Spielkarte beim [[Tarock]])\""}, {"kategorie": "Kartenspielerjargon", "text": "\"Papa Sküs\", [[Gschdiiss]], [[Papa]] Gschdiiss"}]'::jsonb, 'Papa Gschdiiss'),
  ('papa-gschdiiss', 'Papa Gschdiiss', 'der', '', '', 'Wiener Kartentipplerjargon', 'Papa Gstieß', '[{"kategorie": "wörtlich, Kartenspielerjargon", "text": "\"Papa Sküs\" (scherzhafte Bezeichnung der Kartenspieler für den [[Sküs]], die höchste Spielkarte beim [[Tarock]])\""}, {"kategorie": "Kartenspielerjargon", "text": "\"Sküs-Papa\", [[Gschdiiss]], [[Gschdiiss-Papa]] ("}]'::jsonb, 'Waunnsd in Papa Gschdiiss ausseschnoizd, kennan si de aundan brausn!'),
  ('in-gschdiies-papa-haedast-ned-glei-aum-aufaung-aussehaun-diafn-waeu-daunn-host-nix-mea-in-da-hintahaund-ghobd', 'In Gschdiies-Papa hädast ned glei aum Aufaung aussehaun diafn - wäu daunn host nix mea in da Hintahaund ghobd!', '', '', '', 'Wiener Kartentipplerjargon', 'Den Gstieß-Papa hättest du nicht gleich am Anfang raushauen dürfen, weil dann hast du nichts mehr in der Hinterhand gehabt!', '[{"kategorie": "wörtlich", "text": "\"Mit dem Gstieß-Papa so früh rauszugehen, war ein Fehler - denn du hattest dann ja nichts mehr in der Hinterhand!\"  2. Den Gstieß-Papa hast du zu früh verschossen - weil dann bist du mit leeren Händen dagestanden!  3. Du hättest den Gstieß-Papa länger in der Hand behalten sollen - dann hättest du am Schluss noch ein Ass im Ärmel gehabt!"}]'::jsonb, ''),
  ('waunnsd-in-papa-gschdiiss-ausseschnoizd-kennan-si-de-aundan-brausn', 'Waunnsd in Papa Gschdiiss ausseschnoizd, kennan si de aundan brausn!', '', '', '', 'Wiener Kartentipplerjargon', 'Wenn du den Papa Gstiieß rausschnalzt, können sich die anderen brausen!', '[{"kategorie": "wörtlich", "text": "\"Wenn du den Papa Sküs raushaust, können die anderen einpacken!\"  2. Sobald der Papa Gstieß auf dem Tisch liegt, ist für alle anderen Feierabend!  3. Wenn du den Papa Gstieß als Erster ausspielst, haben die anderen nichts mehr zu melden!"}]'::jsonb, ''),
  ('wem-in-gschdiiss-geem', 'wem in Gschdiiss geem', '', '', '', 'Wiener Sprüche, die sitzen!', 'jemandem den Gstieß geben', '[{"kategorie": "wörtlich", "text": "\"jemandem den Laufpass geben\""}, {"kategorie": "", "text": "jemandem eine Abfuhr erteilen"}, {"kategorie": "", "text": "jemandem die Freundschaft aufkündigen"}, {"kategorie": "", "text": "die Beziehung zu jemandem beenden"}]'::jsonb, 'Ea hod fremdpuudad, und si hod eam in Gschdiiss geem!'),
  ('ea-hod-fremdpuudad-und-si-hod-eam-in-gschdiiss-geem', 'Ea hod fremdpuudad, und si hod eam in Gschdiiss geem!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Er hat fremdgepudert, und sie hat ihm den Sküs gegeben!', '[{"kategorie": "wörtlich", "text": "\"Er ist fremdgegangen, worauf sie ihm den Laufpass gegeben hat!\"  2. Er hat sie betrogen, und daraufhin hat sie mit ihm Schluss gemacht!  3. Er ist ihr untreu gewersen – da hat sie ihn eiskalt abserviert!"}]'::jsonb, 'wem in Gschdiiss geem'),
  ('in-gschdiiss-haum', 'in Gschdiiss haum', '', '', '', 'Wiener Sprüche, die sitzen!', 'den Gstieß haben', '[{"kategorie": "wörtlich", "text": "\"das Nachsehen haben\" (eigtl. \"von jemandem mit der höchsten Karte [dem [[Sküs]]] ausgestochen werden\")"}, {"kategorie": "fig.", "text": "\"den Kürzeren ziehen\""}, {"kategorie": "", "text": "\"auf der Strecke bleiben\""}, {"kategorie": "", "text": "\"der Angeschmierte sein\""}, {"kategorie": "", "text": "\"durch die Röhre schauen\""}, {"kategorie": "", "text": "\"den [[Schlauch]] haben\""}, {"kategorie": "", "text": "\"die [[Gurken]] haben\""}]'::jsonb, 'de Guakn haum'),
  ('si-is-mid-an-jingan-duachbrennd-und-ea-hod-in-gschdiiss-ghobd', 'Si is mid an Jingan duachbrennd, und ea hod in Gschdiiss ghobd!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Sie ist mit einem Jüngeren durchgebrannt, und er hat den Gstieß gehabt!', '[{"kategorie": "wörtlich", "text": "\"Sie ist mit einem Jüngeren durchgebrannt, und er hatte das Nachsehen!\"  2. Sie hat sich mit einem Jüngeren davon gemacht, und er war der Angeschmierte!  3. Sie hat sich mit einem Jüngeren aus dem Staub gemacht, und er hat durch die Röhre geschaut!"}]'::jsonb, ''),
  ('si-gschdiissian', 'si gschdiissian', '', '', '', 'Grundwortschatz Wienerisch', 'sich sküsieren', '[{"kategorie": "wörtlich", "text": "\"sich empfehlen\" (abgeleitet vom französischen \"s''excuser\" = \"sich verabschieden\")"}, {"kategorie": "fig.", "text": "sich davonmachen, sich aus dem Staub machen, [[schapian]], [[si]] schraufn"}, {"kategorie": "Kartenspielerjargon", "text": "\"sich mit dem [[Gschdiiss]] ([[Sküs]]) empfehlen\", \"den letzten Stich mit dem [[Gschdiiss]] ([[Sküs]]) einstreifen\", \"sich den letzten Stich mit der höchsten Spielkarte sichern\""}]'::jsonb, 'Zeaschd hoda dem Mentsch a Kind audraad, und daunn hoda si gschdiissiad!'),
  ('zeaschd-hoda-dem-mentsch-a-kind-audraad-und-daunn-hoda-si-gschdiissiad', 'Zeaschd hoda dem Mentsch a Kind audraad, und daunn hoda si gschdiissiad!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Zuerst hat er dem Mädchen ein Kind angedreht, und dann hat er sich sküsiert!', '[{"kategorie": "wörtlich", "text": "\"Zuerst hat er der jungen Frau ein Kind angedreht, und dann hat er sich aus dem Staub gemacht!\"  2. Zuerst hat er das Mädchen geschwängert, und dann hat er Reißaus genommen!  3. Zuerst hat er ihr ein Kind gezeugt, und dann ist er abgehauen!"}]'::jsonb, 'si gschdiissian'),
  ('ea-hod-an-schwoazn-solo-augsoogd-olle-schdich-gmochd-und-si-aum-schluss-aa-noo-gschdiissiad', 'Ea hod an schwoazn Solo augsoogd, olle Schdich gmochd und si aum Schluss aa noo gschdiissiad!', '', '', '', 'Wiener Kartentipplerjargon', 'Er hat einen schwarzen Solo angesagt, alle Stiche gemacht und sich am Schluss auch noch sküsiert!', '[{"kategorie": "wörtlich, Kartenspielerjargon", "text": "\"Er hat einen schwarzen Solo angesagt, alle Stiche gemacht und das Spiel am Schluss auch noch mit dem Sküs beendet!\"  2. Er hat den schwarzen Solo angesagt, alle Stiche eingesammelt und dann auch noch mit dem Gstieß abgeschlossen!  3. Er hat den schwarzen Solo gewagt, alle Stiche eingefahren und beim letzten Stich auch noch den [[Gstieß-Papa]] rausgehauen!"}]'::jsonb, 'si gschdiissian'),
  ('waunnst-an-bagaad-ausoogsd-muassd-min-ultimo-in-letztn-schdich-mochn', 'Waunnst an Bagaad ausoogsd, muassd min Ultimo in letztn Schdich mochn!', '', '', '', 'Wiener Kartentipplerjargon', 'Wenn du einen Pagat ansagst, musst du mit dem Ultimo den letzten Stich machen!', '[{"kategorie": "wörtlich, Kartenspielerjargon", "text": "\"Wenn du beim Tarock einen Pagat ansagst, musst du mit dem Ultimo den letzten Stich machen!\"  2. Beim Tarock gilt: Wer den Pagat ansagt, muss ihn im letzten Stich ausspielen und damit gewinnen!  3. Pagat ansagen heißt, mit der Einser-Tarock den letzten Stich einfahren!"}]'::jsonb, ''),
  ('waunnst-a-bagaadl-ausoogsd-muassd-min-ultimo-in-letztn-schdich-mochn', 'Waunnst a Bagaadl ausoogsd, muassd min Ultimo in letztn Schdich mochn!', '', '', '', 'Wiener Kartentipplerjargon', 'Wenn du ein Pagatl ansagst, musst du mit dem Ultimo den letzten Stich machen!', '[{"kategorie": "wörtlich, Kartenspielerjargon", "text": "\"Wenn du beim Tarock einen Pagat ansagst, musst du mit dem Ultimo den letzten Stich machen!\"  2. Beim Tarock gilt: Wer den Pagat ansagt, muss ihn im letzten Stich ausspielen und damit gewinnen!  3. Pagat ansagen heißt, mit der Einser-Tarock den letzten Stich einfahren!"}]'::jsonb, ''),
  ('bagaad-ultimo', 'Bagaad Ultimo', 'der', '', '', 'Wiener Kartentipplerjargon', 'Pagat-Ultimo', '[{"kategorie": "wörtlich", "text": "\"Pagat-Ultimo\" (vom italienischen\"il bagatto\"=\"Gaukler\" [Spielkartenfigur, die als Straßenkünstler, Schausteller oder Zauberer dargestellt wurde])"}, {"kategorie": "Kartenspielerjargon", "text": "\"niedrigste Stichkarte beim [[Tarock]]\", \"Tarockkarte mit der römischen Zahl \"eins\" (\"I\")\", [[Pagat]], [[Ultimo]]"}]'::jsonb, 'Waunnst in ''Bagaad Ultimo'' ausoogsd, muassd mit da niidrigstn Tarock in letztn Schdich mochn!'),
  ('waunnst-in-bagaad-ultimo-ausoogsd-muassd-mit-da-niidrigstn-tarock-in-letztn-schdich-mochn', 'Waunnst in ''Bagaad Ultimo'' ausoogsd, muassd mit da niidrigstn Tarock in letztn Schdich mochn!', '', '', '', 'Wiener Kartentipplerjargon', 'Wenn du einen Pagat-Ultimo ansagst, musst du mit der niedrigsten Tarock den letzten Stich machen!', '[{"kategorie": "wörtlich, Kartenspielerjargon", "text": "\"Wenn du beim Tarock einen Pagat-Ultimo ansagst, musst du mit der Einsertarock den letzten Stich machen!\"  2. Beim Tarock gilt: Wer den Pagat-Ultimo ansagt, muss ihn beim letzten Stich ausspielen und damit gewinnen!  3. Pagat-Ultimo ansagen heißt, mit der Einser-Tarock den letzten Stich einfahren!"}]'::jsonb, ''),
  ('heast-oida-leebsd-aum-moond-oda-wos', 'Heast, Oida, leebsd aum Moond, oda wos?', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Hör mal, Alter, lebst du auf dem Mond oder was?', '[{"kategorie": "wörtlich", "text": "\"Hey, Kumpel, lebst du hinter dem Mond oder was?\"  2. Bruder, checkst du gar nichts?  3. Hey, Junge, lebst du auf dem Mars, dass du überhaupt nichts mitkriegst?"}]'::jsonb, ''),
  ('ea-hod-ma-min-gschdiiss-in-moond-gfaungd', 'Ea hod ma min Gschdiiss in Moond gfaungd!', '', '', '', 'Wiener Kartentipplerjargon', 'Er hat mir mit dem Gstieß den Mond gefangen!', '[{"kategorie": "wörtlich, Kartenspielerjargon", "text": "\"Er hat mir mit dem [[Sküs]] (höchste Spielkarte im Tarock) den [[Mond]] (zweithöchste Spielkarte im Tarock) gestochen!\""}, {"kategorie": "", "text": "Er hat den [[Papa]] Gstieß gezückt und mir damit den Mond gefangen!  3. Quasi im Vorbeigehen hat er mir den Mond dann auch noch mit dem Gstieß abgestochen!"}]'::jsonb, ''),
  ('dea-woid-ma-deppad-kumma-oiso-hoda-a-softige-kopfwaatschn-oograamd', 'Dea woid ma deppad kumma, oiso hoda a softige Kopfwaatschn oograamd!', '', '', '', 'Wiener Gaunersprache', 'Der wollt mir deppert kommen, also hat er eine saftige Kopfwatsche abgeräumt!', '[{"kategorie": "wörtlich", "text": "\"Der wollt einen auf dicke Hose machen, also hat er eine Kopfwatsche kassiert!\"  2. Der wollt bei mir aufmucken - also hab ich ihm einen ordentlichen [[Hirntaler]] verpasst!  3. Wer mich provoziert, der handelt sich eine Kopfklatsche ein!  4. Wer mir blöd kommt, kriegt eine auf den [[Klapetz]]!"}]'::jsonb, ''),
  ('des-keks-is-so-schdaahoat-des-kaunnsd-ois-tiarlschdoppa-vawendn', 'Des Keks is so schdaahoat, des kaunnsd ois Tiarlschdoppa vawendn!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Das Keks ist so steinhart - das kannst du als Türlstopper verwenden!', '[{"kategorie": "wörtlich", "text": "\"Der Keks ist so steinhart - den kannst du als Türstopper benutzen!\"  2. Der Keks ist steinhart – damit kannst du Nägel in die Wand schlagen!  3. Der Keks ist so knüppelhart, damit könntest du ein Fenster einschlagen!"}]'::jsonb, ''),
  ('a-keks-aum-kroong-mochd-aus-an-deppn-no-laung-kaan-offizia', 'A Keks aum Kroong mochd aus an Deppn no laung kaan Offizia!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Ein Keks am Kragen macht aus ’nem Depp noch lange keinen Offizier!', '[{"kategorie": "wörtlich", "text": "\"Ein goldener Stern am Kragen macht aus einem Deppen noch lange keinen Offizier!\"  2. Ein Affe mit ’nem goldenen Stern am Kragen bleibt immer noch ein Affe!  3. Nur weil er ’nen Offiziersstern trägt, ist er noch lang kein Chef!"}]'::jsonb, ''),
  ('nau-wea-isn-des-siasse-keks-wos-do-grod-einegschneibd-kummd', 'Nau, wea isn des siasse Keks, wos do grod einegschneibd kummd?', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Na, wer ist denn das süße Keks, das da gerade reingeschneit kommt?', '[{"kategorie": "wörtlich", "text": "\"Na, wer ist denn das süße Mädchen, das da gerade reingeschneit kommt?\"  2. Oh, was für ein süßes Ding läuft uns denn da gerade vor die Beine?  3. Wow, schau mal, wer ist denn das Zuckerpüppchen, das hier gerade reinspaziert?"}]'::jsonb, ''),
  ('sein-keks-dazuageem', 'sein Keks dazuageem', '', '', '', 'Wiener Sprüche, die sitzen!', 'seinen Keks dazugeben', '[{"kategorie": "wörtlich", "text": "\"ungefragt seine Meinung äußern\""}, {"kategorie": "", "text": "seinen [[Senf]] dazugeben"}, {"kategorie": "", "text": "\"seinen Kren dazugeben\" (ungefragt einen mehr oder weniger entbehrlichen Kommentar abgeben)"}]'::jsonb, 'Mei Oide glaubd imma, si muass ian Keks dazuageem - aa waunns kaa Sau intaressiad!'),
  ('mei-oide-glaubd-imma-si-muass-ian-keks-dazuageem-aa-waunns-kaa-sau-intaressiad', 'Mei Oide glaubd imma, si muass ian Keks dazuageem - aa waunns kaa Sau intaressiad!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Meine Alte glaubt immer, sie muss ihren Keks dazugeben - auch wenn’s keine Sau interessiert!', '[{"kategorie": "wörtlich", "text": "\"Meine Frau meint immer, sie muss ihren Keks dazugeben - auch wenn’s niemanden interessiert!\"  2. Meine Frau muss immer ihren Senf dazugeben – auch wenn keiner danach gefragt hat!  3. Meine Frau hat für jedes Thema einen Keks auf Lager – gefragt oder ungefragt!"}]'::jsonb, ''),
  ('i-hau-da-glei-aane-aum-keks', 'I hau da glei aane aum Keks!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Ich haue dir gleich eine auf den Keks!', '[{"kategorie": "wörtlich", "text": "\"Ich hau dir gleich eine auf den Schädel!\"  2.  \"Ich geb'' dir gleich eine [[Kopfwatschen]]!\"  3. Gleich kriegst du eine auf''n [[Klapetz]]!"}]'::jsonb, ''),
  ('dea-geed-ma-aum-keks', 'Dea geed ma aum Keks!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Der geht mir auf den Keks!', '[{"kategorie": "wörtlich", "text": "\"Der geht mir auf den Geist!\"  2. \"Der geht mir gehörig auf die Nerven!\"  3. [[Dea geed ma aum Zwicka!]]"}]'::jsonb, ''),
  ('des-geed-ma-aum-keks', 'Des geed ma aum Keks!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Das geht mir auf den Keks!', '[{"kategorie": "wörtlich", "text": "\"Das geht mir auf den Geist!\"  2. \"Das geht mir gehörig auf die Nerven!\"  3. [[Des geed ma aum Zwicka!]]"}]'::jsonb, ''),
  ('do-kumman-aan-de-keks', 'Do kumman aan de Keks!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Da kommen einem die Keks!', '[{"kategorie": "wörtlich", "text": "\"Da bleibt einem die Spucke weg!\"  2. Da haut es einem die Augen aus dem Kopf!  3. Da fällt einem die Kinnlade runter!"}]'::jsonb, ''),
  ('waunna-nix-zum-kaeaewaen-hod-isa-nua-noo-a-hoiwa-mensch', 'Waunna nix zum Kääwän hod, isa nua noo a hoiwa Mensch!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Wenn er nichts zu keppeln hat, ist er nur noch ein halber Mensch!', '[{"kategorie": "wörtlich", "text": "\"Wenn er nichts zu meckern hat, ist er nicht mehr er selbst!\"  2. Kann er nicht motzen, ist er nur noch die Hälfte wert!  3. Hat er keinen Grund zu keppeln, fehlt ihm etwas im Leben!"}]'::jsonb, ''),
  ('de-kepplarei-von-meina-oidn-is-wiara-zeitvatreib-des-hoid-de-beziehung-in-schwung', 'De Kepplarei von meina Oidn is wiara Zeitvatreib - des hoid de Beziehung in Schwung!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Die Kepplerei von meiner Alten ist wie ein Zeitvertreib - das hält die Beziehung in Schwung!', '[{"kategorie": "wörtlich", "text": "\"Die Keppelei meiner Frau ist wie ein Zeitvertreib - das hält die Beziehung in Schwung!\"  2. Eine kleine Streiterei zwischendurch ist für mich und meine Frau wie ein Zeitvertreib – das hält die Beziehung lebendig!  3. Ein bisschen Gezanke von meiner Frau ist für mich wie ein Freizeitspaß – das sorgt für Bewegung in der Partnerschaft!"}]'::jsonb, ''),
  ('dea-kiifaed-aun-seina-zigaan-wiara-hund-aun-sein-kauknochn', 'Dea kiifäd aun seina Zigaan wiara Hund aun sein Kauknochn!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Der kiefelt an seiner Zigarre wie ein Hund an seinem Kauknochen!', '[{"kategorie": "wörtlich", "text": "\"Er nagt an seiner Zigarre wie ein Hund am Kauknochen!\"  2. Der zerkaut seine Zigarre wie ein Hund den Rinderknochen!  3. Der knetet die Zigarre mit den Zähnen wie ein Hund seinen Kauknochen!"}]'::jsonb, ''),
  ('aun-wos-kiifaesd-do-grod-umanaund', 'Aun wos kiifäsd do grod umanaund?', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Woran kiefelst du da gerade heum?', '[{"kategorie": "wörtlich", "text": "\"An was kaust du da so lange herum?\"  2. \"Woran beißt du dir da gerade die Zähne aus?\"  3. Womit schlägst du dich da gerade herum?  3."}]'::jsonb, ''),
  ('si-an-kiifaen-lossn', 'si an kiifän lossn', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'sich einen kiefeln lassen', '[{"kategorie": "", "text": "\"sich einen [[rauchen]] lassen\""}, {"kategorie": "", "text": "\"sich ein [[Blaserl]] genehmigen\""}, {"kategorie": "", "text": "\"sich oral befriedigen lassen\""}]'::jsonb, 'Dea grinsd wiar aana, dea si grod an kiifän hod lossn!'),
  ('dea-grinsd-wiar-aana-dea-si-grod-an-kiifaen-hod-lossn', 'Dea grinsd wiar aana, dea si grod an kiifän hod lossn!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Der grinst wie einer, der sich gerade einen kiefeln hat lassen!', '[{"kategorie": "wörtlich", "text": "\"Der grinst wie einer, der sich gerade einen hat blasen lassen!\"  2. Der grinst, als hätte er grad Weihnachten und Geburtstag auf einmal gehabt!  3. Der grinst wie ein Honigkuchenpferd - als wär ihm gerade einer geblasen worden!"}]'::jsonb, ''),
  ('si-an-bloosn-lossn', 'si an bloosn lossn', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'sich einen blasen lassen', '[{"kategorie": "", "text": "\"sich einen [[kiefeln]] lassen\""}, {"kategorie": "", "text": "\"sich ein [[Blaserl]] genehmigen\""}, {"kategorie": "", "text": "\"sich oral befriedigen lassen\""}]'::jsonb, 'Dea grinsd wiar aana, dea si grod an bloosn hod lossn!'),
  ('dea-grinsd-wiar-aana-dea-si-grod-an-bloosn-hod-lossn', 'Dea grinsd wiar aana, dea si grod an bloosn hod lossn!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Der grinst wie einer, der sich gerade einen blasen hat lassen!', '[{"kategorie": "wörtlich", "text": "\"Der grinst wie einer, der sich gerade einen hat blasen lassen!\"  2. Der grinst, als hätte er grad Weihnachten und Geburtstag auf einmal gehabt!  3. Der grinst wie ein Honigkuchenpferd - als wär ihm gerade einer geblasen worden!"}]'::jsonb, ''),
  ('si-an-rauchn-lossn', 'si an rauchn lossn', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'sich einen rauchen lassen', '[{"kategorie": "", "text": "\"sich einen [[kiefeln]] lassen\""}, {"kategorie": "", "text": "\"sich ein [[Blaserl]] genehmigen\""}, {"kategorie": "", "text": "\"sich oral befriedigen lassen\""}]'::jsonb, 'Dea grinsd wiar aana, dea si grod an rauchn hod lossn!'),
  ('dea-grinsd-wiar-aana-dea-si-grod-an-rauchn-hod-lossn', 'Dea grinsd wiar aana, dea si grod an rauchn hod lossn!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Der grinst wie einer, der sich gerade einen rauchen hat lassen!', '[{"kategorie": "wörtlich", "text": "\"Der grinst wie einer, der sich gerade einen hat blasen lassen!\"  2. Der grinst, als hätte er grad Weihnachten und Geburtstag auf einmal gehabt!  3. Der grinst wie ein Honigkuchenpferd - als wär ihm gerade einer geblasen worden!"}]'::jsonb, ''),
  ('waunns-frische-kipfaln-gibd-schdee-i-sogoa-schoo-in-da-frua-auf', 'Waunns frische Kipfaln gibd, schdee I sogoa schoo in da Frua auf!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Wenn es frische Kipferln gibt, steh ich sogar schon in der Früh auf!', '[{"kategorie": "wörtlich", "text": "\"Wenn es frische Kipferl gibt, bin ich sogar schon frühmorgens aus dem Bett!\"  2. Frische Kipferl locken mich sogar schon früh am Morgen aus den Federn!  3. Wenn’s frische Kipferl gibt, bin ich schon in aller Herrgottsfrüh munter!"}]'::jsonb, ''),
  ('nau-du-kipfal-wos-hostn-heit-wiida-augschdoeoed', 'Nau, du Kipfal, wos hostn heit wiida augschdööd?', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Na, du Kipferl, was hast du denn heute wieder angestellt?', '[{"kategorie": "wörtlich", "text": "\"Na, du Schussel, was hast du denn heute wieder angestellt?\"  2. Na, du Armleuchter, was hast du denn diesmal verbrochen?  3. Na, du [[Dillo]], was hast du denn heute wieder ausgefressen?"}]'::jsonb, ''),
  ('waunn-deara-moonkipfal-siechd-schlickdas-in-zwaa-bissn-owe', 'Waunn deara Moonkipfal siechd, schlickdas in zwaa Bissn owe!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Wenn der ein Mohnkipferl sieht, schluckt er es in zwei Bissen runter!', '[{"kategorie": "wörtlich", "text": "\"Sobald er ein Mohnhörnchen zwischen die Finger bekommt, schluckt er es in zwei Bissen runter!\"  2. Sieht er ein Mohnkipferl, hat es eine Lebenserwartung von drei Sekunden!  3. Er lässt ein Mohnkipferl schneller verschwinden als David Copperfield!"}]'::jsonb, ''),
  ('waunn-deara-nusskipfal-siechd-schlickdas-in-zwaa-bissn-owe', 'Waunn deara Nusskipfal siechd, schlickdas in zwaa Bissn owe!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Wenn der ein Nusskipferl sieht, schluckt er es in zwei Bissen runter!', '[{"kategorie": "wörtlich", "text": "\"Sobald er ein Nusshörnchen zwischen die Finger bekommt, schluckt er es in zwei Bissen runter!\"  2. Sieht er ein Nusskipferl, hat es eine Lebenserwartung von drei Sekunden!  3. Er lässt ein Nusskipferl schneller verschwinden als David Copperfield!"}]'::jsonb, ''),
  ('zu-an-valaengadn-beschdoeoe-i-ma-imma-a-woams-plundakipfal', 'Zu an Valängadn beschdöö I ma imma a woams Plundakipfal!', '', '', '', 'Wiener Kaffeehaus-ABC', 'Zu einem Verlängerten bestelle ich mir immer ein warmes Plunderkipferl!', '[{"kategorie": "wörtlich", "text": "\"Zu einem aromatischen Verlängerten genieße ich am liebsten ein ofenfrisches Plunderkipferl!\"  2. Ein warmes Plunderhörnchen und dazu ein Kaffee mit Milchschaumhäubchen – das ist mein Morgenritual!  3. Zu einem Verlängerten gehört für mich ein warmes, goldbraunes Plunderkipferl!"}]'::jsonb, ''),
  ('a-blech-vanillikipfaln-vaschwind-bei-uns-schnoella-ois-da-grissbaam-schdeed', 'A Blech Vanillikipfaln vaschwind bei uns schnölla ois da Grissbaam schdeed!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Ein Blech Vanillekipferl verschwindet bei uns schneller als der Christbaum steht!', '[{"kategorie": "wörtlich", "text": "\"Die Vanillekipferl sind bei uns weg, bevor der Christbaum überhaupt steht!\"  2. Ein Blech Vanillekipferl ist bei uns schneller weg, als man ‚Weihnachten‘ sagen kann!  3. Bei uns sind Vanillekipferl schneller verputzt, als das Christkind fliegen kann!"}]'::jsonb, ''),
  ('waunnsd-in-a-pinjolikipfal-beissd-schmecksd-sofuad-de-feinan-pinienkean-und-de-siasse-maazipanfuellung', 'Waunnsd in a Pinjolikipfal beissd, schmecksd sofuad de feinan Pinienkean und de siasse Maazipanfüllung!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Wenn du in ein Pignoli-Kipferl beißt, schmeckst du sofort die feinen Pinienkerne und die süße Marzipanfüllung!', '[{"kategorie": "wörtlich", "text": "\"Sobald du in ein Pignoli-Kipferl beißt, spürst du sofort die zarten Pinienkerne und den feinen Marzipangeschmack!\"  2. Beim ersten Biss ins Pignoli-Kipferl entfalten sich sofort das Aroma der Pinienkerne und die Süße des Marzipans!  3. Schon der erste Biss ins Pignoli-Kipferl ist ein Feuerwerk aus Pinienkernaroma und zartem Marzipan!"}]'::jsonb, ''),
  ('fian-eadaepfaesolood-nimm-i-aum-liabstn-kiplfa-waeus-fein-nussig-im-gschmockn-und-fest-im-biss-san-de-ideale-soloodkartoffae', 'Fian Eadäpfäsolood nimm I aum liabstn Kiplfa, wäus fein-nussig im Gschmockn und fest im Biss san - de ideale Soloodkartoffä!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Für den Erdäpfelsalat nehme ich am liebsten Kipfler, weil sie fein-nussig im Geschmack und fest im Biss sind – die ideale Salatkartoffel!', '[{"kategorie": "wörtlich", "text": "\"Für Kartoffelsalat verwende ich am liebsten Kipfler, da sie aromatisch und festkochend sind – perfekt für Salate!\"  2. Kipfler sind meine erste Wahl für Kartoffelsalat: feiner Geschmack und fester Biss!  3. Für einen vollmundigen Erdäpfelsalat empfiehlt sich die Sorte Kipfler – fein-nussig und fest im Biss!"}]'::jsonb, ''),
  ('ea-hod-sein-rausch-in-da-kinettn-ausgschloofn-woeche-de-oaweita-fiad-wossarealn-ausghoom-haum', 'Ea hod sein Rausch in da Kinettn ausgschloofn, wöche de Oaweita fiad Wossarealn ausghoom haum!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Er hat seinen Rausch in der Künette ausgeschlafen, welche die Arbeiter für die Wasserrohre ausgehoben haben!', '[{"kategorie": "wörtlich", "text": "\"Er hat seinen Rausch in der Baugrube ausgeschlafen, welche die Arbeiter für die Wasserleitungen gegraben haben!\"  2. Nach der Zecherei hat er seinen Rausch im Wasserleitungsgraben ausgeschlafen!  3. Er hat sich mitsamt seinem Rausch in die frisch ausgehobene Künette verzogen und dort die Nacht verbracht – quasi im Open-Air-Zimmer!"}]'::jsonb, ''),
  ('a-kistn-bia', 'a Kistn Bia', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'eine Kiste Bier', '[{"kategorie": "wörtlich, Deutschland", "text": "\"ein Kasten Bier\" (vom althochdeutschen \"kista\"=\"Kiste\")"}, {"kategorie": "allg.", "text": "\"eine Bierkiste\", \"ein Bierkasten\""}]'::jsonb, 'I hob fiad Grüüparty zeen Kistn Bia kaufd - noch aana Schdund woa ollas ausgsoffn!'),
  ('i-hob-fiad-grueueparty-zeen-kistn-bia-kaufd-noch-aana-schdund-woa-ollas-ausgsoffn', 'I hob fiad Grüüparty zeen Kistn Bia kaufd - noch aana Schdund woa ollas ausgsoffn!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Ich habe für die Grillparty zehn Kisten Bier gekauft - nach einer Stunde war alles ausgesoffen!', '[{"kategorie": "wörtlich", "text": "\"Für die Grillparty habe ich zehn Kisten Bier besorgt – nach einer Stunde war alles leergetrunken!\"  2. Zehn Kisten Bier für die Grillfeier – und in einer Stunde war alles weggetrunken!  3. Für die Grillparty hab ich zehn Kisten Bier rangeschafft – eine Stunde später war nichts mehr davon übrig!"}]'::jsonb, 'a Kistn Bia'),
  ('noamalaweis-soitn-zwaa-biakistn-fia-fuenf-leit-und-aan-obnd-reichn-ned-so-bei-uns', 'Noamalaweis soitn zwaa Biakistn fia fünf Leit und aan Obnd reichn - ned so bei uns!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Normalerweise sollten zwei Bierkisten für fünf Leute und einen Abend reichen - nicht so bei uns!', '[{"kategorie": "wörtlich", "text": "\"Normalerweise genügen zwei Kisten Bier für fünf Personen an einem Abend – allerdings nicht bei uns!\"  2. Zwei Kisten Bier für fünf Nasen? Klingt viel – nicht jedoch in unserer Runde!  3. Normalerweise reichen zwei Kisten Bier für fünf Leute – doch wir sind da offensichtlich die Ausnahme!"}]'::jsonb, ''),
  ('waunn-dea-auf-seina-glaumpfn-a-solo-aussehaud-bluadn-da-nocha-de-uawaschln', 'Waunn dea auf seina Glaumpfn a Solo aussehaud, bluadn da nocha de Uawaschln!', '', '', '', 'Wienerisches aus Musik, Kunst, Kultur & Medien', 'Wenn der auf seiner Klampfe ein Solo raushaut, bluten dir nachher die Ohrwascheln!', '[{"kategorie": "wörtlich", "text": "\"Wenn der auf seiner Gitarre ein Solo abfeuert, klingeln dir danach die Ohren!\"  2. Wann immer der auf seiner Gitarre ein Solo rausfetzt, pfeifen dir nachher die Ohren!  3. Ein E-Gitarrensolo von ihm ist ein Garant für einen Hörsturz!"}]'::jsonb, ''),
  ('wem-a-glaumpfn-ins-knia-haun', 'wem a Glaumpfn ins Knia haun', '', '', '', 'Wiener Sprüche, die sitzen!', 'jemandem eine Klampfen ins Knie hauen', '[{"kategorie": "wörtlich", "text": "jemandem eine Maurerklammer ins Knie hauen“"}, {"kategorie": "fig.", "text": "\"jemandem einen rostigen Nagel ins Knie rammen\""}, {"kategorie": "", "text": "\"jemandem vors Schienbein treten\""}, {"kategorie": "", "text": "\"jemandem in die Parade fahren\""}, {"kategorie": "", "text": "\"jemandem ans Bein pinkeln\""}, {"kategorie": "", "text": "\"jemandes Ruf verunglimpfen\""}]'::jsonb, ''),
  ('kaum-draasdi-um-hauta-dea-oasch-a-glaumpfn-ins-knia-und-grinst-wiara-braadmaeufrosch', 'Kaum draasdi um, hauta dea Oasch a Glaumpfn ins Knia und grinst wiara Braadmäufrosch!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Kaum drehst du dich um, haut dir der Arsch eine Klampfen ins Knie und grinst wie ein Breitmaulfrosch!', '[{"kategorie": "wörtlich", "text": "\"Kaum drehst du dich um, rammt dir dieser Fiesling einen rostigen Nagel ins Knie  und grinst wie ein Breitmaulfrosch!  2. Sobald du nicht hinschaust, tritt dir der Arsch vors Schienbein und grinst wie ein Honigkuchenpferd!\"  3. Kaum drehst du ihm den Rücken zu, pinkelt dir dieser Widerling ans Bein und grinst dabei auch noch schadenfroh!"}]'::jsonb, 'wem a Glaumpfn ins Knia haun'),
  ('wem-a-glaumpfn-auhaengan', 'wem a Glaumpfn auhängan', '', '', '', 'Wiener Sprüche, die sitzen!', 'jemandem eine Klampfen anhängen', '[{"kategorie": "wörtlich", "text": "\"jemandem eine Maurerklammer anhängen\""}, {"kategorie": "fig.", "text": "\"jemandem einen Makel anhängen\""}, {"kategorie": "", "text": "\"jemandem einen schlechten Ruf anhängen\""}, {"kategorie": "", "text": "\"jemandem eine Laus in den Pelz setzen\""}, {"kategorie": "", "text": "\"jemandem einen Fleck auf die Weste machen\""}]'::jsonb, 'Dea Oasch woid ia unbedingt a Glaumpfn auhängan und hod in Schääf dazööd, dass Gööd aus da Kassa gflaadad hod!'),
  ('dea-oasch-woid-ia-unbedingt-a-glaumpfn-auhaengan-und-hod-in-schaeaef-dazoeoed-dass-goeoed-aus-da-kassa-gflaadad-hod', 'Dea Oasch woid ia unbedingt a Glaumpfn auhängan und hod in Schääf dazööd, dass Gööd aus da Kassa gflaadad hod!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Der Arsch wollte ihr unbedingt eine Klampfen anhängen und hat dem Chef erzählt, dass sie Geld aus der Kasse gefladert hat!', '[{"kategorie": "wörtlich", "text": "\"Dieser Widerling wollte ihr unbedingt einen Makel anhängen und hat dem Chef erzählt, sie hätte Geld aus der Kassa geklaut!\"  2. Der miese Hund wollte ihr eine Laus in den Pelz setzen und hat dem Chef gesteckt, sie hätte Geld geklaut!  3. Der Kerl wollte ihr einen Fleck auf die Weste machen und hat dem Chef weisgemacht, sie hätte Geld aus der Kasse genommen!"}]'::jsonb, 'wem a Glaumpfn auhängan'),
  ('wem-a-glaumpfn-umhaengan', 'wem a Glaumpfn umhängan', '', '', '', 'Wiener Sprüche, die sitzen!', 'jemandem eine Klampfen umhängen', '[{"kategorie": "wörtlich", "text": "\"jemandem eine Maurerklammer umhängen\""}, {"kategorie": "fig.", "text": "\"jemandem einen Makel anhängen\""}, {"kategorie": "", "text": "\"jemandem einen schlechten Ruf anhängen\""}, {"kategorie": "", "text": "\"jemandem eine Laus in den Pelz setzen\""}, {"kategorie": "", "text": "\"jemandem einen Fleck auf die Weste machen\""}]'::jsonb, 'Dea Oasch woid ia unbedingt a Glaumpfn umhängan und hod in Schääf dazööd, dass Gööd aus da Kassa gflaadad hod!'),
  ('dea-oasch-woid-ia-unbedingt-a-glaumpfn-umhaengan-und-hod-in-schaeaef-dazoeoed-dass-goeoed-aus-da-kassa-gflaadad-hod', 'Dea Oasch woid ia unbedingt a Glaumpfn umhängan und hod in Schääf dazööd, dass Gööd aus da Kassa gflaadad hod!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Der Arsch wollte ihr unbedingt eine Klampfen umhängen und hat dem Chef erzählt, dass sie Geld aus der Kasse gefladert hat!', '[{"kategorie": "wörtlich", "text": "\"Dieser Widerling wollte ihr unbedingt einen Makel anhängen und hat dem Chef erzählt, sie hätte Geld aus der Kassa geklaut!\"  2. Der miese Hund wollte ihr eine Laus in den Pelz setzen und hat dem Chef gesteckt, sie hätte Geld geklaut!  3. Der Kerl wollte ihr einen Fleck auf die Weste machen und hat dem Chef weisgemacht, sie hätte Geld aus der Kasse genommen!"}]'::jsonb, 'wem a Glaumpfn umhängan'),
  ('zwa-fiidln-a-glaumpfn-a-mauraklavia-i-bin-hoid-a-weana-i-kaunn-nix-dafia', 'Zwa Fiidln, a Glaumpfn, a Mauraklavia, I bin hoid a Weana, I kaunn nix dafia!', '', '', '', 'Wienerisches aus Musik, Kunst, Kultur & Medien', 'Zwei Fiedeln, eine Klampfen, ein Maurerklavier, ich bin halt ein Wiener, ich kann nichts dafür!', '[{"kategorie": "wörtlich, Liedtext", "text": "\"Zwei Geigen, eine Gitarre, ein Akkordeon, ich bin halt ein Wiener, das liegt mir im Blut!\"  2. \"Zwei Violinen, eine Gitarre, ein Schifferklavier, Wiener durch und durch, das hab ich im Blut!\"  3. Zwei Geigen, eine Gitarre, ein Schifferklavier – was soll ich sagen, das Wienerische steckt halt in mir! (Textzeile des populären Wienerlieds \"I bin hoid a Weana!\")"}]'::jsonb, ''),
  ('heast-glaumpfnwiaga-waunn-di-da-jimi-hendrix-schbueuen-hearad-daeda-da-de-glaumpfn-vabrenna', 'Heast, Glaumpfnwiaga, waunn di da Jimi Hendrix schbüün hearad, däda da de Glaumpfn vabrenna!', '', '', '', 'Wienerisches aus Musik, Kunst, Kultur & Medien', 'Hör mal, Klampfenwürger, wenn dich der Jimi Hendrix spielen hörte, würde er dir die Klampfe verbrennen!', '[{"kategorie": "wörtlich", "text": "\"Hör mal, Gitarrenwürger, wenn Jimi Hendrix dich jetzt spielen hörte, würde er dir die Gitarre verbrennen!\"  2. Pass auf, Gitarrenschinder – wenn Jimi Hendrix dich hören könnte, würde er dich mit den Saiten deiner eigenen Gitarre erwürgen!  3. Na, du Saitenprügler – wenn Jimi Hendrix dich spielen hörte, tät er dir die Saiten eigenhändig runterreißen!"}]'::jsonb, ''),
  ('nau-maasta-oaglsd-heit-wiida-auf-dein-fotzhoowae-oda-bleim-unsare-uawaschln-ausnaumsweis-vaschoond', 'Nau, Maasta, oaglsd heit wiida auf dein Fotzhoowä oda bleim unsare Uawaschln ausnaumsweis vaschoond?', '', '', '', 'Wienerisches aus Musik, Kunst, Kultur & Medien', 'Na, Meister, orgelst du heute wieder auf deinem Fotzhobel oder bleiben unsere Ohrwascheln ausnahmsweise verschont?', '[{"kategorie": "wörtlich", "text": "\"Na, Meister, orgelst du heut wieder auf deiner Mundharmonika oder bleiben unsere Ohren ausnahmsweise verschont?\"  2. Na, Chef, bläst du heut wieder auf deiner Mundharmonika oder bleiben wir ausnahmsweise verschont?  3. Sag, Meister Quetschlippe, wird heut wieder auf der Mundharmonika georgelt oder gönnst du unseren Ohren zur Abwechslung mal ''ne Auszeit?"}]'::jsonb, ''),
  ('na-gee-dea-fotzhoowaeschbueuela-quetscht-jo-nua-noo-luft-aus-seina-blechduudl', 'Na gee, dea Fotzhoowäschbüüla quetscht jo nua noo Luft aus seina Blechduudl!', '', '', '', 'Wienerisches aus Musik, Kunst, Kultur & Medien', 'Na geh, der Fotzhobelspieler quetscht ja nur noch Luft aus seiner Blechdudl!', '[{"kategorie": "wörtlich", "text": "\"\"Na geh, der Mundharmonikaspieler quetscht ja nur noch Luft aus seiner Blechorgel!\"  2. Also wirklich, der Mundharmonikaspieler presst nur Luft aus seinem Instrument!  3. Also ehrlich, der Mundharmonikaspieler macht mehr Wind als Musik!"}]'::jsonb, ''),
  ('des-klappal-vom-briafkostn-is-seitn-letztn-schduam-gaunz-vaboong', 'Des Klappal vom Briafkostn is seitn letztn Schduam gaunz vaboong!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Das Klapperl vom Briefkasten ist seit dem letzten Sturm ganz verbogen!', '[{"kategorie": "wörtlich", "text": "\"Die Einwurfklappe des Briefkastens ist seit dem letzten Sturm total verbogen!\"  2. Die Briefkastenklappe ist durch den ständigen Wind stark verzogen!  3. Der Deckel des Briefeinwurfs wurde durch den letzten Sturm total geknickt!"}]'::jsonb, ''),
  ('mid-de-klappaln-kummsd-ned-weid', 'Mid de Klappaln kummsd ned weid!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Mit diesen Klapperln kommst du nicht weit!', '[{"kategorie": "wörtlich", "text": "\"Mit diesen Klapperlatschen kommst du nicht weit!\"  2. Mit diesen holzbesohlten Sandalen kommst du nicht weit!  3. Mit diesen Klackerschuhen humpelst du keine hundert Meter!"}]'::jsonb, ''),
  ('mia-geeds-klappal', 'Mia geeds Klappal!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Mir geht''s Klapperl!', '[{"kategorie": "wörtlich", "text": "\"Ich habe eine Scheißangst!\"  2. Ich mache vor lauter Angst gleich in die Hose!  3. Mir geht der [[Reis]]!  4. Mir geht die [[Muffen]]!"}]'::jsonb, ''),
  ('ia-geed-dauand-s-klappal', 'Ia geed dauand s''Klappal!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Ihr geht ständig das Klapperl', '[{"kategorie": "wörtlich", "text": "\"Sie hat die Klappe ständig offen!\"  2. Sie hat ihr Mundwerk ständig in Betrieb!  3. Sie redet wie ein Wasserfall!"}]'::jsonb, ''),
  ('dem-muassd-a-jeeds-wuat-aus-da-noosn-ausseklaeaezln', 'Dem muassd a jeeds Wuat aus da Noosn ausseklääzln!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Dem musst du jedes Wort aus der Nase rauskletzeln!', '[{"kategorie": "wörtlich", "text": "\"Dem muss man jedes Wort mühsam aus der Nase ziehen!\"  2. Dem muss man jedes Wort einzeln entlocken!  3. Aus dem bekommt man nur mit Mühe ein Wort heraus!"}]'::jsonb, ''),
  ('dea-beschdoeoed-si-sei-bia-imma-in-ana-hueuesn-waeu-do-kaunna-daunn-es-etikett-wiara-klaana-bua-oweklaeaezln', 'Dea beschdööd si sei Bia imma in ana Hüüsn, wäu do kaunna daunn es Etikett wiara klaana Bua oweklääzln!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Der bestellt sich sein Bier immer in einer Hülsen, weil da kann er dann das Etikett wie ein kleiner Bub runterkletzeln!', '[{"kategorie": "wörtlich", "text": "\"Der bestellt sich sein Bier immer in der Flasche, weil da kann er dann das Etikett wie ein kleiner Bub runterkratzen!\"  2. Bier gibt’s für ihn nur aus der Flasche – denn da kann er dann das Etikett wie ein kleiner Junge abknibbeln!  3. Der braucht sein Bier in der Flasche – sonst kann er das Etikett nicht abfieseln wie ein kleiner Gschropp!"}]'::jsonb, ''),
  ('mei-vooda-dea-oide-taschlziaga-hod-ma-scho-ois-kind-beibrochd-wia-ma-wem-ooklaeaezld', 'Mei Vooda, dea oide Taschlziaga, hod ma scho ois Kind beibrochd, wia ma wem ooklääzld!', '', '', '', 'Wiener Gaunersprache', 'Mein Vater, der alte Taschlzieher, hat mir schon als Kind beigebracht, wie man jemanden abkletzelt!', '[{"kategorie": "wörtlich", "text": "\"Mein Vater, der alte Taschendieb, hat mir schon als Kind beigebracht, wie man jemanden bestiehlt!\"  2. Mein Vater, der alte Langfinger, hat mir schon als Kind beigebracht, wie man Leute abzieht!  3. Mein Alter, ein echter Griffelkönig, hat mir von klein auf beigebracht, wie man den Leuten das Geld aus der Tasche zieht!"}]'::jsonb, ''),
  ('des-preispickal-lossd-si-ned-ooklaeaezln', 'Des Preispickal lossd si ned ooklääzln!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Das Preispickerl lässt sich nicht abkletzeln!', '[{"kategorie": "wörtlich", "text": "\"Der Preisaufkleber lässt sich mit den Fingernägeln nicht abkratzen!\"  2. Der Preisaufkleber ist mit den Fingernägeln nicht ablösbar!  3. Das Preispickerl geht mit den Fingernägeln nicht runter!"}]'::jsonb, ''),
  ('klaeaezl-ned-in-ana-tua-aun-deina-fotzblaeaezn-sunst-entzindsa-si-nua-noo-mea', 'Klääzl ned in ana Tua aun deina Fotzblääzn, sunst entzindsa si nua noo mea!', '', '', '', 'Krank & kuriert auf Wienerisch', 'Kletzle nicht in einer Tour an deiner Fotzbletzen, sonst entzündet sie sich nur noch mehr!', '[{"kategorie": "wörtlich", "text": "\"Fingere nicht andauernd an deiner Fieberblase rum, sonst entzündet sie sich nur noch mehr!\"  2. Hör auf, dauernd an deiner Fieberblase herumzuzupfen, sonst entzündet sie sich nur noch mehr!  3. Fummel nicht die ganze Zeit an deiner Fierblase rum, sonst eitert sie nur noch mehr!"}]'::jsonb, ''),
  ('klaeaezl-ned-mid-d-finga-in-da-noosn', 'Klääzl ned mid d''Finga in da Noosn!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Kletzle nicht mit den Fingern in der Nase!', '[{"kategorie": "", "text": "Fingerl nicht in der Nase herum!  2. Bohr nicht in der Nase!  3. Fummel nicht in der Nase herum!  4. (Deutschland): \"Hör auf, in der Nase zu popeln!\""}]'::jsonb, ''),
  ('waunnst-briafmarkn-saummaesd-muassd-a-richtiga-klaeaezla-sei', 'Waunnst Briafmarkn saummäsd, muassd a richtiga Klääzla sei!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Wenn du Briefmarken sammelst, musst du ein richtiger Kletzler sein!', '[{"kategorie": "wörtlich", "text": "\"Wenn du Briefmarken sammelst, musst du ein richtiger Fuzler sein!\"  2. Wer Briefmarken sammelt, muss ein richtiger Knibbler sein!  3. Wer Briefmarken sammelt, ist doch automatisch ein Fitzler!"}]'::jsonb, ''),
  ('ea-nennt-si-philatelist-owa-fia-uns-isa-ned-vueue-mea-ois-a-schdinknoamaala-marknklaeaezla', 'Ea nennt si Philatelist, owa fia uns isa ned vüü mea ois a schdinknoamaala  ''Marknklääzla''!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Er nennt sich Philatelist, aber für uns ist er nicht viel mehr als ein stinknormaler Markenkletzler!', '[{"kategorie": "wörtlich", "text": "\"Er bezeichnet sich als Philatelist, aber für uns ist er nur ein ganz gewöhnlicher Markenfuzler!\"  2. Er nennt sich Philatelist, aber wir sagen: ein Markenknibbler im Kleinformat!  3. Er nennt sich Philatelist – für uns bleibt er ein Fummler, der mit seinen Fingernägeln tagein, tagaus nur Gummipapier abkratzt!"}]'::jsonb, ''),
  ('wia-kau-ma-nua-a-briafmarknsaummla-sei-de-ewiche-klaeaezlarei-muass-an-doch-aum-keks-gee', 'Wia kau ma nua a Briafmarknsaummla sei? De ewiche Klääzlarei muass an doch aum Keks gee!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Wie kann man nur ein Briefmarkensammler sein? Die ewige Kletzlerei muss einem doch am Keks gehen!', '[{"kategorie": "wörtlich", "text": "\"Wie kann man nur Briefmarkensammler sein? Die ewige Fitzelei muss einem doch auf den Geist gehen!\"  2. Wie kann man nur Briefmarken sammeln? Das ständige Gefummel muss doch irgendwann nerven!  3. Wie kann man nur Briefmarkensammler sein? Bei der ständigen Fuzelei wird man doch irgendwann blöd im Kopf!"}]'::jsonb, ''),
  ('da-klaane-schdibitzd-schoo-wia-sei-oida-owa-bis-jetzd-sans-zum-glick-nua-zuckaln', 'Da Klaane schdibitzd schoo wia sei Oida - owa bis jetzd sans zum Glick nua Zuckaln!', '', '', '', 'Wiener Gaunersprache', 'Der Kleine stibitzt schon wie sein Alter - aber bis jetzt sind''s zum Glück nur Zuckerln!', '[{"kategorie": "wörtlich", "text": "\"Der Kleine klaut schon wie sein Alter - aber bis jetzt sind''s zum Glück nur Bonbons!\"  2. Der Kleine stiehlt schon wie sein Vater – aber bisher zum Glück nur Bonbons!  3. Der Kleine macht schon Beute wie sein Alter – doch bis jetzt zum Glück nur Naschwerk!"}]'::jsonb, ''),
  ('dea-typ-do-is-a-gwiifda-schdibitza-lossd-ollas-midgee-wos-ned-niet-und-nooglfest-is', 'Dea Typ do is a gwiifda Schdibitza - lossd ollas midgee, wos ned niet- und nooglfest is!', '', '', '', 'Wiener Gaunersprache', 'Der Typ da ist ein gewiefter Stibitzer – lässt alles mitgehen, was nicht niet- und nagelfest ist!', '[{"kategorie": "wörtlich", "text": "\"Der Typ da ist ein raffinierter Langfinger – er nimmt alles mit, was nicht festgeschraubt ist!\"  2. Der Kerl ist ein abgefeimter Schlitzfinger - krallt sich alles, was nicht festgebunden ist!  3. Der Typ da ist ein erfahrener Abgreifer – klaut alles, was nicht wegläuft!"}]'::jsonb, ''),
  ('de-klaeaetzn-ghean-vuam-bockn-a-poa-schdund-im-wossa-eigwaakd', 'De Kläätzn ghean vuam Bockn a poa Schdund im Wossa eigwaakd!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Die Dörrbirnen gehören vor dem Backen ein paar Stunden in Wasser eingeweicht!', '[{"kategorie": "wörtlich", "text": "\"Die Dörrbirnen müssen vor dem Backen einige Stunden in Wasser eingeweicht werden!\"  2. Die getrockneten Birnen sollten vor dem Backen mehrere Stunden in Wasser quellen!  3. Vor dem Backen sollten die Dörrbirnen einige Stunden im Wasserbad liegen!"}]'::jsonb, ''),
  ('pass-auf-dass-da-de-klaeaetzn-ned-vabrennsd', 'Pass auf, dass da de Kläätzn ned vabrennsd!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Pass auf, dass du dir die Kletzen nicht verbrennst!', '[{"kategorie": "wörtlich", "text": "\"Pass auf, dass du dir die Finger nicht verbrennst!\"  2. Pass auf deine Griffel auf, sonst verbrennst du dich noch!  3. Gib Acht, steck da nicht deine Pfoten rein, sonst verbrennst du dich!"}]'::jsonb, ''),
  ('heast-du-klaeaetzn-schdoeoe-di-ned-so-au-a-jaukal-wiad-di-ned-glei-umbringan', 'Heast, du Kläätzn, schdöö di ned so au - a Jaukal wiad di ned glei umbringan!', '', '', '', 'Krank & kuriert auf Wienerisch', 'Hör mal, du Kletzen, stell dich nicht so an - ein Jaukerl wird dich nicht gleich umbringen!', '[{"kategorie": "wörtlich", "text": "\"Hör mal, du Weichei, stell dich nicht so an - eine kleine Injektion wird dich nicht gleich umbringen!\"  2. Hör zu, du Memme, mach nicht so ein Theater – die Spritze bringt dich nicht um!  3. Halt still, du Mimose – das ist nur ein kleiner Stich!"}]'::jsonb, ''),
  ('de-oide-klaeaetzn-hockd-in-gaunz-toog-aum-fensta-und-richt-de-leit-aus', 'De oide Kläätzn hockd in gaunz Toog aum Fensta und richt de Leit aus!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Die alte Kletzen hockt den ganzen Tag am Fenster und richtet die Leute aus!', '[{"kategorie": "wörtlich", "text": "\"Die alte Schachtel hockt den ganzen Tag am Fenster und zerreißt sich das Maul über die Leute!\"  2. Die alte Vogelscheuche hängt den ganzen Tag am Fenster und lästert über jeden, der vorbeigeht!  3. Die alte [[Grammel]] sitzt den ganzen Tag am Fenster und gibt über jeden ihren Senf ab!"}]'::jsonb, ''),
  ('de-oide-klaeaetzn-sitzd-schoo-wiida-in-da-sakristei-und-zoeoed-de-messweinfloschn', 'De oide Kläätzn sitzd schoo wiida in da Sakristei und zööd de Messweinfloschn!', '', '', '', 'Religiöses & Göttliches auf Wienerisch', 'Die alte Kletzen sitzt schon wieder in der Sakristei und zählt die Messweinflaschen!', '[{"kategorie": "wörtlich", "text": "\"Die alte Klosterfrau sitzt schon wieder in der Sakristei und zählt die Messweinflaschen!\"  2. Die alte Ordensschwester sitzt schon wieder im Sakristeikammerl und zählt die Messweinflaschen wie andere ihr Erspartes!  3. Die alte Klostertrutsche hockt in der Sakristei und bewacht den Messwein wie der Teufel die Sünder!"}]'::jsonb, ''),
  ('waunn-i-noo-laung-auf-dem-hoatn-sessl-sitzn-muass-kriag-i-noo-klaeaetzn-in-oasch', 'Waunn I noo laung auf dem hoatn Sessl sitzn muass, kriag I noo Kläätzn in Oasch!', '', '', '', 'Krank & kuriert auf Wienerisch', 'Wenn ich noch lange auf diesem harten Sessel sitzen muss, krieg ich noch Kletzen im Arsch!', '[{"kategorie": "wörtlich", "text": "\"Wenn ich noch lange auf diesem harten Sessel sitzen muss, krieg ich noch Hämorrhoiden!\"  2. Lange bleib ich auf diesem Sessel nicht mehr sitzen, sonst wachsen mir Hämorrhoiden!  3. Sitz ich hier weiter, hab ich bald Rosettenknoten in XXL!"}]'::jsonb, ''),
  ('du-host-jo-lauta-klaeaetzn-ind-hoa-woast-leichd-im-woid', 'Du host jo lauta Kläätzn ind Hoa - woast leichd im Woid?', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Du hast ja lauter Kletzen im Haar - warst du vielleicht im Wald?', '[{"kategorie": "wörtlich", "text": "\"Du hast ja lauter Schmutzklumpfen im Haar - warst du etwa im Wald?\"  2. In deinen Haaren hängen lauter Schmutzbatzen – warst du im Wald spazieren?  3. Du hast ja das halbe Unterholz im Haar – warst du im Wald?"}]'::jsonb, ''),
  ('waunn-d-oma-klaeaetznbrood-bockd-is-da-heilige-oobnd-nimma-weit', 'Waunn d''Oma Kläätznbrood bockd, is da Heilige Oobnd nimma weit!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Wenn die Oma Kletzenbrot bäckt, ist der Heilige Abend nicht mehr weit!', '[{"kategorie": "wörtlich", "text": "\"Wenn Oma ihr Früchtebrot bäckt, steht Weihnachten vor der Tür!\"  2. Sobald unsere Großmutter ihr Kletzenbrot macht, dauert es nicht mehr lange bis Heiligabend!  3. Wenn der Duft von Omas Kletzenbrot durchs Haus zieht, ist Weihnachten nicht mehr fern!"}]'::jsonb, ''),
  ('mit-dem-glump-kaunnsd-heechstns-a-buanheidl-zasaagln-owa-kaa-hoizbreedl', 'Mit dem Glump kaunnsd heechstns a Buanheidl zasaagln, owa kaa Hoizbreedl!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Mit dem Klump kannst du höchstens ein Burenhäutel zersägen, aber sicher kein Holzbrett!', '[{"kategorie": "wörtlich", "text": "\"Mit dem Pfuschzeug kannst du höchstens ''ne Burenwurst zersägen, aber sicher kein Holzbrett!\"  2. Mit dem Schrottwerkzeug kriegst du vielleicht eine Burenwurst halbiert, aber kein Brett durch!  3. Mit dem Ramsch kannst du allenfalls eine Burenwurst einritzen, aber Holz? Vergiss es!"}]'::jsonb, ''),
  ('mit-dem-glumpad-kaunnsd-heechstns-a-buanheidl-zasaagln-owa-kaa-hoizbreedl', 'Mit dem Glumpad kaunnsd heechstns a Buanheidl zasaagln, owa kaa Hoizbreedl!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Mit dem Klumpert kannst du höchstens ein Burenhäutel zersägen, aber sicher kein Holzbrett!', '[{"kategorie": "wörtlich", "text": "\"Mit dem Pfuschzeug kannst du höchstens ''ne Burenwurst zersägen, aber sicher kein Holzbrett!\"  2. Mit dem Schrottwerkzeug kriegst du vielleicht eine Burenwurst halbiert, aber kein Brett durch!  3. Mit dem Ramsch kannst du allenfalls eine Burenwurst einritzen, aber Holz? Vergiss es!"}]'::jsonb, ''),
  ('raam-dei-glump-weg', 'Raam dei Glump weg!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Räum dein Klump weg!', '[{"kategorie": "wörtlich", "text": "Räum dein Zeug weg!  2. Pack den Kram weg!  3. Räum deinen Krempel auf!"}]'::jsonb, ''),
  ('raam-dei-glumpad-weg', 'Raam dei Glumpad weg!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Räume dein Klumpert weg!', '[{"kategorie": "wörtlich", "text": "\"Räum dein Zeug weg!\"  2. Pack den Kram weg!  3. Räum deinen Krempel auf!"}]'::jsonb, ''),
  ('a-laungs-glumpad', 'a laungs Glumpad', '', '', '', 'Wiener Sprüche, die sitzen!', 'ein langes Klumpert', '[{"kategorie": "wörtlich, bezogen auf Personen", "text": "\"ein langer Lackel\""}, {"kategorie": "", "text": "\"ein langer Lulatsch\""}, {"kategorie": "", "text": "\"ein langer Schlacks\""}, {"kategorie": "", "text": "\"ein langes Trumm\""}]'::jsonb, 'Neebm dem laungan Glumpad kumm I ma vua wiara Schlisslauhänga!'),
  ('neebm-dem-laungan-glumpad-kumm-i-ma-vua-wiara-schlisslauhaenga', 'Neebm dem laungan Glumpad kumm I ma vua wiara Schlisslauhänga!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Neben diesem langen Klumpert komm ich mir vor wie ein Schlüsselanhänger!', '[{"kategorie": "wörtlich", "text": "\"Neben diesem langen Lulatsch komm ich mir vor wie ein Schlüsselanhänger!\" 2. Neben diesem langen Schlacks fühl ich mich wie ein Schlüsselanhänger!  3. Ich komm mir neben diesem langen Trumm vor wie ein Jausensackerl neben ''nem Kleiderschrank!"}]'::jsonb, 'a laungs Glumpad'),
  ('so-a-kluppn-is-wia-mei-schwiigamuada-zwickd-si-iwaroi-fest-obsd-wueuesd-oda-ned', 'So a Kluppn is wia mei Schwiigamuada - zwickd si iwaroi fest, obsd wüüsd oda ned!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'So eine Kluppe ist wie meine Schwiegermutter – zwickt sich überall fest, ob du willst oder nicht!', '[{"kategorie": "wörtlich", "text": "\"So eine Wäscheklammer ist wie meine Schwiegermutter – klemmt sich überall fest, ob du willst oder nicht!\"  2. So eine Kluppe ist wie meine Schwiegermutter – einmal festgebissen, brauchst du die Feuerwehr zum Lösen!  3. So eine Wäscheklammer ist wie meine Schwiegermutter – klemmt sich an, und plötzlich gehört ihr der halbe Wäscheständer!"}]'::jsonb, ''),
  ('de-heimat-vom-knoofae-is-zentralasien-wos-heit-no-wueuede-foaman-davoo-gibd', 'De Heimat vom Knoofä is Zentralasien, wos heit no wüüde Foaman davoo gibd!', '', '', '', 'Botanik und Pflanzen auf Wienerisch', 'Die Heimat des Knoblauchs ist Zentralasien, wo es heute noch wilde Formen davon gibt!', '[{"kategorie": "wörtlich", "text": "\"Ursprünglich stammt der Knoblauch aus Zentralasien, wo auch heute noch Wildformen wachsen!\"  2. In Zentralasien, seiner ursprünglichen Heimat, gedeiht Knoblauch teilweise noch in wilder Form!  3. Der Knoblauch hat seinen Ursprung in Zentralasien, wo man ihn noch in wilder Form findet!"}]'::jsonb, ''),
  ('a-knoofae-sei', 'a Knoofä sei', '', '', '', 'Wiener Sprüche, die sitzen!', 'ein Knofel sein', '[{"kategorie": "wörtlich", "text": "\"eine Stinkzwiebel sein\""}, {"kategorie": "scherzhaft für", "text": "\"ein Unglücksbringer sein\""}, {"kategorie": "", "text": "\"Murphys Liebing sein\" (d.h. jemand, der etwas durch seine bloße Anwesenheit zum Misslingen bringt)"}]'::jsonb, 'Imma waunn du kummsd, passiad iagendaa Maleea - du bist echt a Knoofä!'),
  ('imma-waunn-du-kummsd-passiad-iagendaa-maleea-du-bist-echt-a-knoofae', 'Imma waunn du kummsd, passiad iagendaa Maleea - du bist echt a Knoofä!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Immer wenn du kommst, passiert irgendein Malheur – du bist echt ein Knofel!', '[{"kategorie": "wörtlich", "text": "\"Jedes Mal, wenn du da bist, passiert irgendein Malheur – du bist der reinste Unglücksbringer!\"  2. Sobald du kommst, gibt’s Ärger – du bist einfach ein schwarzer Kater!  3. Immer wenn du auftauchst, geht was schief – du bist wie Freitag, der 13., nur in Menschengestalt!"}]'::jsonb, 'a Knoofä sei'),
  ('dea-is-a-knoofae-fia-jedn', 'Dea is a Knoofä fia jedn!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Der ist ein Knofel für jeden!', '[{"kategorie": "wörtlich", "text": "\"Der ist eine Stinkzwiebel für jedermann\""}, {"kategorie": "scherzhaft für", "text": "Der bringt jedem nur Unglück!"}, {"kategorie": "", "text": "Der ist für jeden ein wandelndes Malheur!  4. Der ist Murphy''s Liebling für jedermann! (d.h. eine Person, die etwas durch ihre bloße Anwesenheit zum Misslingen bringt)"}]'::jsonb, ''),
  ('suachst-an-zwiifae-findst-an-knofae', 'Suachst an Zwiifä, findst an Knofä!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Suchst du einen Zwiebel, findest du einen Knofel [=Knoblauch]!', '[{"kategorie": "wörtlich", "text": "\"Man findet selten, was man sucht!\"  2. (scherzhaft für): Suchen heißt nicht immer finden!   3. (fig.) Das Leben ist kein Wunschkonzert!"}]'::jsonb, ''),
  ('i-reib-da-in-boin-min-knoofae-ei-dassd-eam-wenigstns-riachst', 'I reib da in Boin min Knoofä ei, dassd eam wenigstns riachst!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Ich reibe dir den Ball mit Knoblauch ein, damit du ihn wenigstens riechst!', '[{"kategorie": "Fußballerjargon, scherzhaft für", "text": "\"Du wirst heute keinen einzigen Ball sehen!\"  2. \"Heute siehst du nur Gras!\"  3. \"Heute bist du nur Zuschauer!\""}]'::jsonb, ''),
  ('in-dera-knoofaehittn-haengd-de-tapaeaetn-von-d-waend-und-schdingd-noch-bochanan-knoofae', 'In dera Knoofähittn hängd de Tapäätn von d''Wänd und schdingd noch bochanan Knoofä!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'In dieser Knoblauchhütte hängt die Tapete von den Wänden und stinkt nach gebackenem Knoblauch!', '[{"kategorie": "wörtlich", "text": "\"In dieser Knoblauchhütte hängt die Tapete von den Wänden und stinkt nach frittiertem Knoblauch!\"  2. In dieser Knoblauchhütte löst sich die Tapete von den Wänden, und der Geruch von frittiertem Knoblauch liegt schwer in der Luft!  3. In dieser Knoblauchhütte hängt die Tapete wie eine müde Zunge von der Wand, und eine Knoblauchwolke umarmt jeden Gast, der sich hier reintraut!"}]'::jsonb, ''),
  ('gemma-ind-balkanhittn-ums-eck-niagands-gibds-bessare-tschewaapaln-mid-an-kajmak-und-an-ajvar', 'Gemma ind Balkanhittn ums Eck - niagands gibds bessare Tschewaapaln mid an Kajmak und an Ajvar!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Gehen wir in die Balkanhütte ums Eck - nirgends gibt''s bessere Tschewaaperln mit Kajmak und Ajvar!', '[{"kategorie": "wörtlich", "text": "\"Gehen wir in die Balkanhütte ums Eck - nirgends gibt''s bessere Cevapcici mit Kajmak und Ajvar!\"  2. Lass uns ins Balkanlokal gleich ums Eck gehen – die Cevapcici mit Kajmak und Ajvar sind dort unschlagbar!  3. Komm, wir gehen ins Balkanrestaurant um die Ecke – bessere Cevapcici mit Kajmak und Ajvar findest du nirgends!"}]'::jsonb, ''),
  ('kaana-waass-wofia-dea-knopf-do-is-oiso-druck-ma-aafoch-drauf-und-schau-ma-wos-passiad', 'Kaana waass, wofia dea Knopf do is - oiso druck ma aafoch drauf und schau ma, wos passiad!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Keiner weiß, wofür der Knopf da ist – also drücken wir einfach drauf und schauen wir, was passiert!', '[{"kategorie": "wörtlich", "text": "\"Keine Ahnung, wozu der Knopf da gut ist – also draufhauen und überraschen lassen!\"  2. Wenn keiner weiß, was der Knopf macht, heißt das, er will gedrückt werden!  3. Niemand kennt die Funktion des Knopfs – also probieren wir einfach aus, was passiert, wenn man draufdrückt!"}]'::jsonb, ''),
  ('da-knopf-aun-da-lood-is-locka-und-muass-festgschraubd-wean', 'Da Knopf aun da Lood is locka und muass festgschraubd wean!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Der Knopf an der Lade ist locker und muss festgeschraubt werden!', '[{"kategorie": "wörtlich", "text": "\"Der Knopf an der Schublade ist locker und muss festgeschraubt werden!\"  2. Der Griff an der Schublade wackelt und muss nachgezogen werden!  3. Der Schubladenknauf ist lose und gehört festgeschraubt!"}]'::jsonb, ''),
  ('dea-klaane-knopf-frissd-mea-pala-ois-sei-vooda', 'Dea klaane Knopf frissd mea Pala ois sei Vooda!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Der kleine Knopf frisst mehr Pala als sein Vater!', '[{"kategorie": "wörtlich", "text": "\"Der kleine Knopf verdrückt mehr Palatschinken als sein Vater!\"  2. Der kleine Stöpsel räumt den Palatschinkenteller schneller leer als sein Vater!  3. Der kleine Knirps rollt die Palatschinken schneller weg als sein Papa das Bier!"}]'::jsonb, ''),
  ('so-a-knopf-und-glaubd-ea-is-da-kaisa-von-wean', 'So a Knopf - und glaubd, ea is da Kaisa von Wean!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'So ein Knopf - und glaubt, er ist der Kaiser von Wien!', '[{"kategorie": "wörtlich", "text": "\"So eine Witzfigur - und glaubt, er ist der Kaiser von Wien!\"  2. So ein lächerliches Männchen - und spielt sich auf wie der Kaiser von Wien!  3. So ein Kasperl - und hält sich für den Mittelpunkt der Welt!"}]'::jsonb, ''),
  ('a-quetschn-hod-entweeda-tastn-oda-knepfaln-de-schdeirische-jeednfois-is-a-knepfalharmonika', 'A Quetschn hod entweeda Tastn oda Knepfaln - de Schdeirische jeednfois is a Knepfalharmonika!', '', '', '', 'Wienerisches aus Musik, Kunst, Kultur & Medien', 'Eine Quetschen hat entweder Tasten oder Knöpferln - die Steirische jedenfalls ist eine Knöpferlharmonika!', '[{"kategorie": "wörtlich", "text": "\"Ein Akkordeon besitzt entweder Tasten oder Knöpfe – die Steirische ist auf jeden Fall eine Knopfgriff-Harmonika!\"  2. Beim Akkordeon gibt’s Tasten- oder Knopfversionen – und die Steirische spielt in der Knöpferl-Liga!  3. Akkordeons gibt es mit Tasten oder mit Knöpfen – die Steirische gehört zu den diatonischen Knopfgriffinstrumenten!"}]'::jsonb, ''),
  ('an-knopf-mochn', 'an Knopf mochn', '', '', '', 'Wiener Sprüche, die sitzen!', 'einen Knopf machen', '[{"kategorie": "wörtlich", "text": "\"einen Knoten machen\""}, {"kategorie": "", "text": "\"eine Masche binden\""}, {"kategorie": "", "text": "\"einen Knoten schnüren\""}, {"kategorie": "", "text": "\"eine Schleife binden\""}]'::jsonb, 'Dea is wiara klaana Bua - dea kaunn beim Schuachzuabindn bis heit kaan gscheidn Knopf mochn!'),
  ('dea-is-wiara-klaana-bua-dea-kaunn-beim-schuachzuabindn-bis-heit-kaan-gscheidn-knopf-mochn', 'Dea is wiara klaana Bua - dea kaunn beim Schuachzuabindn bis heit kaan gscheidn Knopf mochn!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Der ist wie ein kleiner Bub - der kann beim Schuhezubinden bis heute keinen g''scheiten Knopf machen!', '[{"kategorie": "wörtlich", "text": "\"Er ist wie ein kleiner Junge – bis heute kann er keine richtige Masche mit seinen Schnürsenkeln binden!\"  2. Der ist ein Kindskopf geblieben – nicht mal die Schuhschleife kriegt er ordentlich hin!  3. Er benimmt sich wie ein Kind – er bekommt beim Schuhezubinden noch immer keine vernünftige Masche hin!"}]'::jsonb, 'an Knopf mochn'),
  ('endlich-is-eam-da-knopf-aufgaungan', 'Endlich is eam da Knopf aufgaungan!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Endlich ist ihm der Kopf aufgegangen!', '[{"kategorie": "wörtlich", "text": "\"Endlich hat er''s begriffen!\"  2. Endlich ist bei ihm der Groschen gefallen!  3. Endlich ist ihm ein Licht aufgegangen!"}]'::jsonb, ''),
  ('mia-geed-da-knopf-auf', 'Mia geed da Knopf auf!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Mir geht der Knopf auf!', '[{"kategorie": "wörtlich", "text": "\"Mir geht das Licht auf!\"  2. Jetzt hat''s Klick bei mir gemacht!  3. Jetzt ist der Groschen bei mir gefallen!"}]'::jsonb, ''),
  ('an-knopf-im-hian-haum', 'an Knopf im Hian haum', '', '', '', 'Wiener Sprüche, die sitzen!', 'einen Knopf im Hirn haben', '[{"kategorie": "wörtlich", "text": "\"einen Knoten im Hirn haben\""}, {"kategorie": "", "text": "\"ein Brett vor dem Kopf haben\""}, {"kategorie": "", "text": "\"einen Kurzschluss im Hirn haben\""}, {"kategorie": "", "text": "\"auf der Leitung stehen\""}, {"kategorie": "", "text": "[[aum]] Schlauch schdee"}]'::jsonb, 'Vua lauta Paragrafn hob I jetzd an Knopf im Hian!'),
  ('vua-lauta-paragrafn-hob-i-jetzd-an-knopf-im-hian', 'Vua lauta Paragrafn hob I jetzd an Knopf im Hian!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Vor lauter Paragraphen hab ich jetzt einen Knopf im Hirn!', '[{"kategorie": "wörtlich", "text": "\"Vor lauter Paragraphen hab ich jetzt einen Knoten im Hirn!\"  2. Bei so vielen Paragraphen schaltet mein Hirn aufr Durchzug!  3. \"Vor lauter Paragraphen hab ich jetzt einen Kurzschluss im Hirn!\""}]'::jsonb, 'an Knopf im Hian haum'),
  ('si-an-knopf-ind-fiass-mochn', 'si an Knopf ind Fiass mochn', '', '', '', 'Wiener Sprüche, die sitzen!', 'sich einen Knopf in die Füße machen', '[{"kategorie": "wörtlich", "text": "\"sich die Beine verknoten\""}, {"kategorie": "Fußballerjargon", "text": "\"über die eigenen Füße stolpern\""}, {"kategorie": "", "text": "\"sich selbst ein Bein stellen\""}]'::jsonb, 'Beim Jooga hob I ma fost an Knopf ind Fiass gmochd!'),
  ('beim-jooga-hob-i-ma-fost-an-knopf-ind-fiass-gmochd', 'Beim Jooga hob I ma fost an Knopf ind Fiass gmochd!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Beim Yoga hab ich mir fast einen Knopf in die Füße gemacht!', '[{"kategorie": "wörtlich", "text": "\"Beim Yoga habe ich mir fast einen Knoten in die Beine gemacht!\"  2. Beim Yoga hab ich mir fast einen Makramee-Knoten aus den Beinen gemacht!  3. Beim Yoga hätte ich meine Beine fast zu einer Schleife verknotet!“"}]'::jsonb, 'si an Knopf ind Fiass mochn'),
  ('kaum-hoda-in-boin-foida-aa-schoo-hii-ois-haeda-si-an-knopf-ind-fiass-gmochd', 'Kaum hoda in Boin, foida aa schoo hii - ois häda si an Knopf ind Fiass gmochd!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Kaum hat er den Ball, fällt er auch schon hin - als hätte er sich einen Knopf in die Füße gemacht!', '[{"kategorie": "wörtlich", "text": "\"Kaum hat er den Ball, stolpert er schon über seine eigenen Füße - als hätte er sich einen Knoten in die Beine gemacht!\"  2. Er hat den Ball und kippt gleich um – als hätte er einen Knoten in den Beinen!  3. Kaum hat er den Ball, stolpert er auch schon – als hätte er sich die Füße verknotet!"}]'::jsonb, 'si an Knopf ind Fiass mochn'),
  ('kaan-knopf-haum', 'kaan Knopf haum', '', '', '', 'Wiener Sprüche, die sitzen!', 'keinen Knopf haben', '[{"kategorie": "wörtlich", "text": "\"keinen Groschen haben\""}, {"kategorie": "", "text": "\"arm wie eine Kirchenmaus sein\""}, {"kategorie": "", "text": "\"auf dem Trockenen sitzen\""}]'::jsonb, 'Dea hod kaan Knopf, wüü owa schlemman wiara Keenig!'),
  ('dea-hod-kaan-knopf-wueue-owa-schlemman-wiara-keenig', 'Dea hod kaan Knopf, wüü owa schlemman wiara Keenig!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Der hat keinen Knopf, will aber schlemmen wie ein König!', '[{"kategorie": "wörtlich", "text": "\"Der hat keinen Groschen, will aber schlemmen wie ein König!\"  2. Der ist blank wie eine abgebrannte Glühbirne, will aber groß essen gehen!  3. Er hat keinen Knopf im Börserl, aber Lust auf ein Fünf-Gänge-Menü mit Silberbesteck!"}]'::jsonb, ''),
  ('a-palatschinkn-muass-hauchdinn-sei-waunnsdas-geengs-liachd-hoitst-muassd-de-zeidung-drunta-leesn-kenna', 'A Palatschinkn muass hauchdinn sei - waunnsdas geengs Liachd hoitst, muassd de Zeidung drunta leesn kenna!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Eine Palatschinke muss hauchdünn sein - wenn du sie gegen das Licht hältst, musst du die Zeitung drunter lesen können!', '[{"kategorie": "wörtlich", "text": "\"Eine Palatschinke gehört hauchdünn – so dünn, dass man darunter noch die Zeitung lesen kann!\"  2. Eine gute Palatschinke ist hauchdünn – durchsichtig wie ein Blatt Pergament!  3. Die perfekte Palatschinke ist wie ein Vorhang aus Teig – durchsichtig und leicht!"}]'::jsonb, ''),
  ('dea-hod-an-koffan-lossn-wiara-hiinniche-tuba', 'Dea hod an koffan lossn wiara hiinniche Tuba!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Der hat gekoffert wie ''ne hinnige Tuba!', '[{"kategorie": "wörtlich", "text": "\"Der hat gefurzt wie eine kaputte Tuba!\"  2. Aus seinem Arsch hat''s gepfiffen wie aus einer rostigen Ziehharmonika!  3. Der hat einen pfeifen lassen wie ein altes Schiffshorn!"}]'::jsonb, ''),
  ('dea-koffad-duachs-buero-ois-daeda-de-woeoed-rettn-woin-dabei-suachda-nua-sein-autoschlissl', 'Dea koffad duachs Büro, ois däda de Wööd rettn woin - dabei suachda nua sein Autoschlissl!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Der koffert durchs Büro, als täte er die Welt retten wollen – dabei sucht er nur seinen Autoschlüssel!', '[{"kategorie": "wörtlich", "text": "\"Der wuselt durchs Büro, als würde er die Welt retten wollen – dabei sucht er nur seinen Autoschlüssel!\"  2. Er wirbelt durchs Büro wie ein aufgescheuchtes Huhn – dabei sucht er nur den Autoschlüssel!  3. Er hastet durchs Büro, als wäre er im Rettungseinsatz für die ganze Welt – in Wahrheit sucht er aber nur seinen Autoschlüssel!"}]'::jsonb, ''),
  ('schau-da-de-zwaa-johannistriabla-au-de-glueuen-si-geengseitig-au-wia-zwa-haasse-oofnrealn', 'Schau da de zwaa Johannistriabla au - de glüün si geengseitig au wia zwa haasse Oofnrealn!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Schau dir die zwei Johannistriebler an - die glühen sich gegenseitig an wie zwei heiße Ofenröhreln!', '[{"kategorie": "wörtlich", "text": "\"Schau dir die zwei Johannistriebler an – die glühen ja füreinander wie zwei heiße Ofenrohre!\"  2. Schau dir die zwei Spätverliebten an – die brennen ja füreinander wie zwei heißverliebte Glühbirnen!  3. Schau dir die beiden Silberlöwen an – die glühen vor heißer Leidenschaft füreinander!"}]'::jsonb, ''),
  ('schdee-kaane-lecha-in-trottoa', 'Schdee kaane Lecha in Trottoa!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Steh keine Löcher in den Trottoir!', '[{"kategorie": "wörtlich", "text": "\"Steh keine Löcher in den Gehsteig!\"  2. (fig.) \"Schlag keine Wurzeln!\"  3. Steh hier nicht rum wie festgetackert!  4. Mach den Beton nicht weich!  5. Willst du Wurzeln schlagen oder mitkommen?"}]'::jsonb, ''),
  ('vuam-broodn-soitn-de-kooischbrossn-kuaz-blauschiad-wean-damits-zoata-san', 'Vuam Broodn soitn de Kooischbrossn kuaz blauschiad wean, damits zoata san!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Vor dem Braten sollten die Kohlsprossen kurz blanchiert werden, damit sie zarter sind!', '[{"kategorie": "wörtlich", "text": "\"Kohlsprossen sollten vor dem Braten kurz blanchiert werden, um sie zarter zu machen\"  2. Wenn du die Kohlsprossen vorher kurz ins heiße Wasser gibst, sind sie beim Braten zarter!  3. Einmal kurz abgekocht, und schon sind die Kohlsprossen beim Braten schön weich!"}]'::jsonb, ''),
  ('in-da-pfaunn-greesde-kooischbrossaln-mit-an-ahoansirup-und-woiniss-san-a-echta-geheimtipp', 'In da Pfaunn greesde Kooischbrossaln mit an Ahoansirup und Woiniss san a echta Geheimtipp!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'In der Pfanne geröstete Kohlsprosserln mit Ahornsirup und Walnüssen sind ein echter Geheimtipp!', '[{"kategorie": "wörtlich", "text": "\"Kohlsprosserln, in der Pfanne goldbraun geröstet und mit Ahornsirup sowie Walnüssen veredelt, sind ein echter Gaumenschmaus!\"  2. Fein geröstete Kohlsprosserln mit süßem Ahornsirup und nussigem Crunch – ein Geheimtipp für Foodies!  3. Kohlsprosserln mal anders – mit Ahornsirup und Walnüssen aus der Pfanne sind sie der Hit!"}]'::jsonb, ''),
  ('mia-schmeckn-koibrockaln-ois-a-broodana-mit-a-bissl-an-schbeck-bsundas-guad', 'Mia schmeckn Koibrockaln ois a Broodana mit a bissl an Schbeck bsundas guad!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Mir schmecken Kohlbrockerln gebraten mit ein bisschen Speck besonders gut!', '[{"kategorie": "wörtlich", "text": "\"Mir schmecken Kohlsprossen gebraten mit ein bisschen Speck besonders gut!\"  2. Ich mag gebratene Kohlsprossen mit etwas Speck besonders gern!  3. Ich esse Kohlsprossen am liebsten angebraten mit ein bisschen Speck!"}]'::jsonb, ''),
  ('schbrossaln-geen-supa-mit-muskatnuss-und-butta', 'Schbrossaln geen supa mit Muskatnuss und Butta!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Sprosserln gehen super mit Muskatnuss und Butter!', '[{"kategorie": "wörtlich", "text": "\"Kohlsprossen harmonieren hervorragend mit Muskatnuss und Butter!\"  2. Kohlsprossen lassen sich ausgezeichnet mit Butter und Muskatnuss verfeinern!  3. Butter und Muskatnuss unterstreichen das Aroma von Kohlsprossen hervorragend!"}]'::jsonb, ''),
  ('dinsta-kochsolood-mid-eabsn-is-a-aafoche-owa-gschmackige-beiloog', 'Dinsta Kochsolood mid Eabsn is a aafoche, owa gschmackige Beiloog!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Gedünsteter Kochsalat mit Erbsen ist eine einfache, aber g''schmackige Beilage!', '[{"kategorie": "wörtlich", "text": "\"Gedünsteter Kochsalat mit Erbsen ist eine einfache, aber schmackhafte Gemüsebeilage!\"  2. In der Einbrenn zubereiteter Kochsalat mit Erbsen ist eine schlichte, aber geschmackvolle Beilage!  3. Kochsalat mit jungen Erbsen, sanft in einer Einbrenn gegart, bietet eine elegante Begleitung zu Fleisch- und Fischgerichten!"}]'::jsonb, ''),
  ('friara-hod-a-frau-mit-stil-imma-a-frische-kombinaeaesch-im-kostn-ghobd', 'Friara hod a Frau mit Stil imma a frische Kombinääsch im Kostn ghobd!', '', '', '', 'Wiener Wörter mit schillernder Geschichte', 'Früher hat eine Frau mit Stil immer eine frische Kombinesch im Kasten g’habt!', '[{"kategorie": "wörtlich", "text": "\"Früher hatte eine stilbewusste Frau immer ein sauberes Unterkleid im Schrank!\"  2. Wer früher was auf sich hielt, hatte die Kombinesch frisch gebügelt im Schrank – direkt neben dem guten Unterrock!  3. Eine Dame von Welt erkannte man früher an der Kombinesch – und am Lavendelduft im Kasten!"}]'::jsonb, ''),
  ('oone-mei-kombinaeaesch-schdeig-i-auf-ka-eisn', 'Oone mei Kombinääsch schdeig I auf ka Eisn!', '', '', '', 'Wiener Mechaniker-Slang', 'Ohne meine Kombinesch steig ich auf kein Eisen!', '[{"kategorie": "wörtlich, Bikerjargon", "text": "\"Ohne meinen einteiligen Rennanzug steige ich auf kein Motorrad!\"  2. Ohne meinen Ganzkörper-Pyjama schmeiß ich mich auf keine Maschine!  3. Bevor ich den Feuerstuhl besteige, hau ich mich immer erst in meinen Rennoverall!"}]'::jsonb, ''),
  ('waunnsd-de-rueckbaunk-umleegsd-kaunnsd-in-dera-kombinaeaesch-fost-zoeoetn', 'Waunnsd de Rückbaunk umleegsd, kaunnsd in dera Kombinääsch fost zöötn!', '', '', '', 'Wiener Mechaniker-Slang', 'Wennst die Rückbank umlegst, kannst du in dieser Kombinesch fast zelten!', '[{"kategorie": "wörtlich", "text": "\"Wenn du die Rückbank umlegst, kannst in diesem Kombinationskraftwagen fast zelten!\"  2. Legt man die Rückbank um, bietet dieser Kombi fast Platz wie ein Zelt!  3. Klappt man die Rückbank weg, wird der Kombi zum Camper!"}]'::jsonb, ''),
  ('de-neichn-schuach-san-eissasd-kommood', 'De neichn Schuach san eissasd kommood!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Die neuen Schuhe sind äußerst kommod!', '[{"kategorie": "wörtlich", "text": "\"Die neuen Schuhe sind äußerst bequem!\"  2. Die neuen Schuhe sitzen wie angegossen!  3. Die neuen Schuhe sind äußerst angenehm zu tragen!"}]'::jsonb, ''),
  ('im-umgaung-mit-seine-hackla-woara-imma-kommood', 'Im Umgaung mit seine Hackla woara imma kommood!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Im Umgang mit seinen Hacklern war er immer kommod!', '[{"kategorie": "wörtlich", "text": "\"Im Umgang mit seinen Arbeitern war er immer nett und unkompliziert!\"  2. Er war gegenüber seinen Arbeitern immer fair und umgänglich!  3. Er pflegte im Umgang mit seinen Arbeitern stets eine wohlwollende, unkomplizierte Art!"}]'::jsonb, ''),
  ('schdott-dassa-uns-hueuefd-knoozda-blaeaed-in-da-eckn-und-schaud-uns-beim-hackln-zua', 'Schdott dassa uns hüüfd, knoozda blääd in da Eckn und schaud uns beim Hackln zua!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Statt dass er uns hilft, knotzt er blöd in der Ecke und schaut uns beim Hackeln zu!', '[{"kategorie": "wörtlich", "text": "\"Anstatt uns zu helfen, sitzt er untätig in der Ecke und schaut uns beim Arbeiten zu!\"  2. Während wir schuften, hockt er blöd herum und sieht uns beim Malochen zu!  3. Anstatt selbst mit Hand anzulegen, hockt er wie ein Klotz in der Ecke und schaut uns beim Arbeiten zu!"}]'::jsonb, ''),
  ('nochn-essn-knotz-i-mi-aufd-kautsch-und-ria-kaan-finga-mea', 'Nochn Essn knotz I mi aufd Kautsch und ria kaan Finga mea!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Nach dem Essen knotz'' ich mich auf die Couch und rühre keinen Finger mehr!', '[{"kategorie": "wörtlich", "text": "\"Nach dem Essen lass ich mich bequem auf der Couch nieder und rühre keinen Finger mehr!\"  2. Nach dem Essen mache ich es mir auf der Couch bequem und tu gar nichts mehr!  3. Nach dem Essen lümmel ich mich aufs Sofa und bewege mich nicht mehr vom Fleck!"}]'::jsonb, ''),
  ('dea-hod-mi-schdundnlaung-beknoozd-bis-i-endlich-jo-gsoogd-hob', 'Dea hod mi schdundnlaung beknoozd, bis I endlich ''Jo'' gsoogd hob!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Der hat mich stundenlang beknotzt, bis ich endlich ''Ja'' gesagt habe!', '[{"kategorie": "wörtlich", "text": "\"Der hat mich so lange bekniet, bis ich schließlich ‚Ja‘ sagte!\"  2. Er hat so lange auf mich eingeredet, bis ich schließlich zugestimmt habe!  3. Er hat mich so lange belagert, bis ich letztlich nachgegeben habe!"}]'::jsonb, ''),
  ('knooz-ned-umanaund-wiara-nossa-moeoesock', 'Knooz ned umanaund wiara nossa Möösock!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Knotz nicht herum wie ein nasser Mehlsack!', '[{"kategorie": "wörtlich", "text": "\"Lungere nicht herum wie ein nasser Mehlsack!\"  2. Hock nicht herum wie ein nasser Fetzen!  3. Häng hier nicht rum wie ein fauler Hund!"}]'::jsonb, ''),
  ('schdundnlaung-im-wiatshaus-umadumknoozn-is-imma-no-bessa-ois-zua-oidn-haamgee', 'Schdundnlaung im Wiatshaus umadumknoozn is imma no bessa ois zua Oidn haamgee!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Stundenlang im Wirtshaus herumknotzen ist immer noch besser als zur Alten heimgeh''n!', '[{"kategorie": "wörtlich", "text": "\"Stundenlang im Gasthaus herumzulungern ist immer noch angenehmer, als zur Frau nach Hause zu gehen!\"  2. Ewig im Wirtshaus herumzuhocken ist immer noch besser, alsmit der Alten  daheim Stress zu haben!  3. Lieber den Hintern im Wirtshaus platt sitzen als daheim den Kopf waschen lassen!"}]'::jsonb, ''),
  ('si-niidaknoozn', 'si niidaknoozn', '', '', '', 'Grundwortschatz Wienerisch', 'sich niederknotzen', '[{"kategorie": "wörtlich", "text": "\"sich niederknotzen\" (vom mittelhochdeutschen \"knorzen\"=\"knotig werden\")"}, {"kategorie": "allg.", "text": "\"sich irgendwo bequem niederlassen\", \"sich niederhocken\", \"es sich bequem machen\", ausruhen, entspannen, faulenzen"}]'::jsonb, 'Knooz di moi niida und bloos aus!'),
  ('knooz-di-moi-niida-und-bloos-aus', 'Knooz di moi niida und bloos aus!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Knotz dich mal nieder und blas aus!', '[{"kategorie": "wörtlich", "text": "\"Hock dich mal nieder und lass Luft ab!\"  2. Mach''s dir bequem und atme erst mal durch!  3. Hock dich hin und puste mal durch!"}]'::jsonb, 'si niidaknoozn'),
  ('dea-oide-knooza-kummd-nua-ausn-haus-waunn-da-briaftrooga-es-goeoed-bringd', 'Dea oide Knooza kummd nua ausn Haus, waunn da Briaftrooga es Gööd bringd!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Der alte Knotzer kommt nur aus dem Haus, wenn der Briefträger das Geld bringt!', '[{"kategorie": "wörtlich", "text": "\"Der alte Nichtstuer kommt nur aus dem Haus, wenn der Briefträger das Geld bringt!\"  2. Der alte Faulpelz kommt nur raus, wenn’s Kohle gibt!  3. Der alte Stubenhocker geht nur zur Tür, wenn der Briefträger die Pension bringt!"}]'::jsonb, ''),
  ('dea-zimmaknooza-kennd-in-himmae-nua-vom-fensta-aus', 'Dea Zimmaknooza kennd in Himmä nua vom Fensta aus!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Dieser Zimmerknotzer kennt den Himmel nur vom Fenster aus!', '[{"kategorie": "wörtlich", "text": "\"Dieser Stubenhocker sieht den Himmel nur durch die Fensterscheibe!\"  2. Dieser Drinnenbleiber kennt die Außenwelt nur von seinem Fenster aus!  3. Dieser Sofaheld geht nie raus – den Himmel kennt er nur durchs Fenster!"}]'::jsonb, ''),
  ('nochn-raadlfoan-zischd-a-krachal-wia-schampanja-im-hois', 'Nochn Raadlfoan zischd a Krachal wia Schampanja im Hois!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Nach dem Radfahren zischt ein Kracherl wie Champagner im Hals!', '[{"kategorie": "wörtlich", "text": "\"Nach dem Radeln zischt ''ne Sprudel-Limo wie Champagner im Hals!\"  2. Nach dem Radfahren schmeckt eine kühle Limonade besonders erfrischend!  3. Das Kracherl perlt nach dem Radeln wie Champagner den Hals runter!"}]'::jsonb, ''),
  ('du-kralawaatschade-vooglscheichn', 'Du kralawaatschade Vooglscheichn!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Du klapprige, verkrümmte Vogelscheuche!', '[{"kategorie": "wörtlich", "text": "\"Du erbärmliches, altes Klappergestell!\"  2. \"Du schief zusammengeschraubte, klapprige Vogelscheuche!\"  3. \"Du schirches, schief zusammengezimmertes Knochengestell!\""}]'::jsonb, ''),
  ('dea-hod-kralawaatschade-haxn-ois-warada-sei-leebm-laung-auf-an-ross-griidn', 'Dea hod kralawaatschade Haxn, ois warada sei Leebm laung auf an Ross griidn!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Der hat kralawatscherte Haxen, als wäre er sein Leben lang auf einem Ross geritten!', '[{"kategorie": "wörtlich", "text": "\"Der hat krumme Beine, als wäre er sein Leben lang auf einem Pferd gesessen!\"  2. Der ist so krummbeinig, als wär er schon als Kind auf einem Ross zur Schule geritten!  3. So schiefe Beine bekommst du nur, wenn du unzählige Stunden im Sattel verbringst!"}]'::jsonb, ''),
  ('de-kralawaatschade-hittn-schaud-aus-ois-daeds-beim-naechstn-niasa-zsaummfoin', 'De kralawaatschade Hittn schaud aus, ois däds beim nächstn Niasa zsaummfoin!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Die kralawatscherte Hütte sieht aus, als täte sie beim nächsten Nieser zusammenfallen!', '[{"kategorie": "wörtlich", "text": "\"Die windschiefe Hütte sieht aus, als würde sie beim nächsten Nieser zusammenbrechen!\"  2. Die klapprige Hütte sieht aus, als würde sie beim nächsten Nieser in sich zusammenfallen!  3. Die wacklige Bude steht so windschief da, als wollte sie beim nächsten Sturm zusammenbrechen!"}]'::jsonb, ''),
  ('a-kralawaatschade-gschichd', 'a kralawaatschade Gschichd', '', '', '', 'Wiener Sprüche, die sitzen!', 'eine kralawatscherte Geschichte', '[{"kategorie": "wörtlich", "text": "\"eine schräge Geschichte\""}, {"kategorie": "", "text": "\"eine abgefahrene Geschichte\""}, {"kategorie": "", "text": "\"eine skurrile Story\""}]'::jsonb, 'So a kralawaatschade Gschichd däd ned amoi im Kino wea glaum!'),
  ('so-a-kralawaatschade-gschichd-daed-ned-amoi-im-kino-wea-glaum', 'So a kralawaatschade Gschichd däd ned amoi im Kino wea glaum!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'So eine kralawatscherte Geschichte täte nicht einmal im Kino irgendwer glauben!', '[{"kategorie": "wörtlich", "text": "\"So eine schräge Geschichte würde nicht einmal im Kino jemand glauben!\"  2. So eine abgefahrene Geschichte würde selbst im Film niemand für wahr halten!  3. So eine skurrile Story glaubt dir kein Mensch, nicht einmal auf der Leinwand!"}]'::jsonb, 'a kralawaatschade Gschichd'),
  ('dea-schwingd-sein-kraumpn-ois-daeda-an-tunnoeoe-noch-australien-groom', 'Dea schwingd sein Kraumpn, ois däda an Tunnöö noch Australien groom!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Der schwingt seinen Krampen, als täte er einen Tunnel nach Australien graben!', '[{"kategorie": "wörtlich", "text": "\"Der schwingt seine Spitzhacke, als wollte er persönlich einen Tunnel nach Australien graben!\"  2. Der schwingt seine Spitzhacke, als wolle er sich bis ans andere Ende der Welt durchgraben!  3. Der schlägt mit der Spitzhacke zu, als hätte er vor, den Erdkern freizulegen!"}]'::jsonb, ''),
  ('kraumpn-oeoelendicha-moogsd-ned-auzaan', 'Kraumpn, öölendicha, moogsd ned auzaan?', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Krampen, elendiger, magst nicht anziehen?', '[{"kategorie": "wörtlich", "text": "\"Du elendiger Gaul - so zieh doch endlich!\"  2. \"Du lahmer Ackergaul – so beweg dich doch endlich!\"  3. Hopp, du alter Klepper - ziehen, oder ich brenn dir den Schweif ab!"}]'::jsonb, ''),
  ('dea-kraumpn-hod-a-gsichd-do-schbringd-da-hund-freiwuellich-in-zwinga', 'Dea Kraumpn hod a Gsichd, do schbringd da Hund freiwüllich in Zwinga!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Der Krampen hat ein G’sicht, da springt der Hund freiwillig in den Zwinger!', '[{"kategorie": "wörtlich", "text": "\"Diese Schirchperchte hat ein Gesicht, da springt der Hund freiwillig in den Zwinger!\"  2. Diese alte Schabracke hat so ein gehässiges G''schau, dass sich der Hund nimmer aus dem Zwinger traut!  3. Beim Anblick dieser bösen Vogelscheuche springt der Hund nicht nur in den Zwinger, sondern zieht auch gleich den Riegel zu!"}]'::jsonb, ''),
  ('mit-dem-oidn-kraumpn-locksd-kaan-mea-hintan-oofn-viare', 'Mit dem oidn Kraumpn locksd kaan mea hintan Oofn viare!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Mit diesem alten Krampen lockst du keinen mehr hinterm Offen nach vor!', '[{"kategorie": "wörtlich", "text": "\"Mit diesem ausgedienten Ding lockst du keinen mehr hinterm Offen hervor!\"  2. Mit diesem alten Klump kannst du niemanden mehr beeindrucken!  3. Mit diesem ausrangierten Stück gewinnst du nicht mal ''nen Blumentopf!"}]'::jsonb, ''),
  ('da-tisch-is-aus-an-kraumpadn-hoiz-zimmad-rau-volla-schblitta-und-oone-schliff', 'Da Tisch is aus an kraumpadn Hoiz zimmad - rau, volla Schblitta und oone Schliff!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Der Tisch ist aus krampertem Holz gezimmert – rau, voller Splitter und ohne Schliff!', '[{"kategorie": "wörtlich", "text": "\"Der Tisch ist aus unbehandeltem Holz gezimmert – mit rauer Oberfläche, Splittern an den Kanten und ganz ohne Schleifarbeit!\"  2. Ein Tisch ist aus rohem Holz gebaut – sägerau, splitternd, unbearbeitet!  3. Der Tisch ist aus rustikalem, handgesägtem Holz gezimmert – kantig, hart, nicht poliert!"}]'::jsonb, ''),
  ('fiad-feine-gsoeoeschoft-is-dea-vueue-z-kraumpad-z-laut-zu-direkt-und-zu-grob-im-auftreedn', 'Fiad feine Gsööschoft is dea vüü z''kraumpad - z''laut, zu direkt und zu grob im Auftreedn!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Für die feine Gesellschaft ist der viel zu krampert – zu laut, zu direkt und zu grob im Auftreten!', '[{"kategorie": "wörtlich", "text": "\"Für die feine Gesellschaft ist er viel zu unbeholfen – zu laut, zu direkt, zu grob im Auftreten!\"  2. Er wirkt in der feinen Gesellschaft deplatziert – zu grobschlächtig, zu direkt, zu ungehobelt!  3. Für kultivierte Kreise wirkt er wie ein Holzklotz – zu laut, zu roh, zu unangepasst!"}]'::jsonb, ''),
  ('a-kraumpada-woong-liigd-umkippd-im-schlaumm-de-raadln-tiaf-eigsunkn', 'A kraumpada Woong liigd umkippd im Schlaumm - de Raadln tiaf eigsunkn!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Ein kramperter Wagen liegt umgekippt im Schlamm - die Räder tief eingesunken!', '[{"kategorie": "wörtlich", "text": "\"Ein sperriger Wagen liegt umgekippt im Morast – die Räder tief eingesunken!\"  2. Ein klobiger Karren ist im Schlamm umgestürzt, die Räder stecken fest!  3. Ein unförmiger Fuhrwagen liegt umgekippt im Schlamm – festgefahren, mit versunkenen Rädern!"}]'::jsonb, ''),
  ('ea-is-kraumpad-wias-ungschliffane-hoiz-in-seina-weakschdott-kantig-roo-und-hoat', 'Ea is kraumpad wias ungschliffane Hoiz in seina Weakschdott - kantig, roo und hoat!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Er ist krampert wie das ungeschliffene Holz in seiner Werkstatt - kantig, roh und hart!', '[{"kategorie": "wörtlich", "text": "\"Er ist so grob wie das ungehobelte Holz in seiner Werkstatt - kantig, roh und hart!\"  2. Er ist so rau wie das rohe Holz auf seiner Werkbank – kantig, ungeschliffen und ohne jeden Feinsinn!  3. Er ist so ungeschliffen wie das Holz, das er täglich zusägt – grob, kantig und ohne jede Weichheit!"}]'::jsonb, ''),
  ('des-foeoed-miass-ma-ookraumpn-bevua-d-humusschichd-auftroong-wiad', 'Des Fööd miass ma ookraumpn, bevua d''Humusschichd auftroong wiad!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Das Feld müssen wir abkrampen, bevor die Humusschicht aufgetragen wird!', '[{"kategorie": "wörtlich", "text": "\"Wir müssen den Feldboden erst mit der Hacke lockern und freilegen, bevor die Humusschicht aufgetragen wird!\"  2. Vor dem Auftrag des Humus muss der Feldboden gelockert und die Deckschicht entfernt werden!  3. Wir müssen den Oberboden mit der Spitzhacke auflockern, ehe der Humus aufgebracht werden kann!"}]'::jsonb, ''),
  ('da-oide-is-kraumpndia-owa-zaach-wiara-drootsaeu', 'Da Oide is kraumpndia, owa zaach wiara Drootsäu!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Der Alte ist krampendürr, aber zäh wie ein Drahtseil!', '[{"kategorie": "wörtlich", "text": "\"Der Alte ist knochendürr, aber zäh wie Schuhleder!\"  2. Der Alte ist dünn wie ein Stock, aber zäh wie Leder!  3. Er ist wie ein alter Ast – dürr, rissig, aber noch lange nicht gebrochen!"}]'::jsonb, ''),
  ('da-wei-is-kraumpnsaua-dea-beissd-si-in-da-guagl-fest-wiara-rostiga-noogl', 'Da Wei is kraumpnsaua - dea beissd si in da Guagl fest wiara rostiga Noogl!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Der Wein ist krampensauer – der beißt sich in der Gurgel fest wie ein rostiger Nagel!', '[{"kategorie": "wörtlich", "text": "\"Der Wein ist extrem sauer – er beißt sich im Rachen fest wie ein rostiger Nagel!\"  2. Der Wein ist so beißend sauer - er frisst sich wie Salzsäure durch die Speiseröhre!  3. Der Wein ist so sauer - der zieht einem ja die Backenzähne raus!"}]'::jsonb, ''),
  ('mei-oide-is-kraumpnsaua-des-siich-i-schoo-aum-zuckn-in-ian-gsichd', 'Mei Oide is kraumpnsaua - des siich I schoo aum Zuckn in ian Gsichd!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Meine Alte ist krampensauer - das sehe ich schon am Zucken in ihrem Gesicht!', '[{"kategorie": "wörtlich", "text": "\"Meine Alte ist stinksauer – das merkt man schon an ihrer zuckenden Miene!\"  2. Meine Alte kocht – und zwar so, dass ihr der Dampf schon aus’m Gesicht steigt!  3. Meine Alte ist stocksauer – ihr Gesicht zuckt wie ''ne kaputte Neonröhre kurz vorm Explodieren!"}]'::jsonb, ''),
  ('noochn-drittn-schluck-vom-wiat-sein-raafnbeissa-woa-mei-zauschmoeoez-geschichte', 'Noochn drittn Schluck vom Wiat sein Raafnbeissa woa mei Zauschmööz Geschichte!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Nach dem dritten Schluck vom Reifenbeißer des Wirten war mein Zahnschmelz Geschichte!', '[{"kategorie": "wörtlich", "text": "\"Nach dem dritten Schluck vom wirtshauseigenen [[Heckenklescher]] war mein Zahnschmelz hinüber!\"  2. Der Säurebomber vom Wirt hat mir den Zahnschmelz in Sekunden weggeputzt!  3. Der Essigbrenner vom Wirt hat mir das Grinsen aus dem Mund gebrannt!"}]'::jsonb, ''),
  ('in-wiatn-sei-kraumpnschdaana-ziagd-da-de-zeend-ausn-zaufleisch', 'In Wiatn sei Kraumpnschdaana ziagd da de Zeend ausn Zaufleisch!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Der Krampensteiner vom Wirten zieht dir die Zähne aus dem Zahnfleisch!', '[{"kategorie": "wörtlich", "text": "\"Der Wein vom Wirten ist so extrem sauer - der zieht dir die Zähne aus dem Zahnfleisch!\"  2. Das ist kein Wein, das ist ein Essigbrenner - der brennt dir die Zähne aus dem Zahnfleisch!  3. Der Säurebomber vom Wirt zieht dir in Sekunden die Zähne aus dem Zahnfleisch!"}]'::jsonb, '')
